
-- Limpa a tabela e reinsere todos os criterios
TRUNCATE TABLE public.perguntas_rtrs CASCADE;

-- Insere todas as perguntas oficiais da matriz RTRS da planilha Certificação RTRS.xlsx
INSERT INTO public.perguntas_rtrs (secao, numero_criterio, enunciado, ponderacao, orientacao, criterio, ativo, ordem) VALUES
('Princípio 1: Cumprimento da Legislação e Boas Práticas Empresariais', '1.1.1', 'Existe um conhecimento demonstrável das responsabilidades segundo as leis aplicáveis.', 'Imediata', 'Orientação 1.1.1 - 1.1.2 Os produtores precisam ter acesso à informação para saber o que é exigido deles por lei. Exemplos incluem a manutenção de um registo de leis ou acesso à consultoria jurídica relevante. O cumprimento dos preceitos legais deverá ser verificado por meio: • da verificação de dados públicos disponíveis sobre o cumprimento, quando houver; • de entrevistas com funcionários e partes interessadas; e • de observações de campo. A Interpretação Nacional do país correspondente definirá o escopo da verificação da lei aplicável que os produtores precisam cumprir e fornecer evidências do cumprimento durante a auditoria.

Orientação para Produtores e Auditores: Com o intuito de verificar o cumprimento dos requisitos legais ambientais pelos produtores, o auditor deverá verificar: a) Se o produtor tem uma Licença Ambiental Rural. b) Se o produtor não tiver uma Licença ambiental, ele/ela deverá ter uma licença e/ou autorização emitidas pela autoridade competente. Por exemplo, os CAR ou LAU emitidos pela Secretaria do Meio Ambiente (SEMA), no estado do Mato Grosso. c) Se o produtor não tiver a Licença ambiental ou a licença e/ou autorização emitidos pela autoridade competente, ele já deverá ter solicitado esses documentos. Leis aplicáveis: a) CLT – Consolidação das Leis do Trabalho b) Código Florestal (Lei 4771, 1965) – Padrões Regulamentares c) Ver no Anexo 6:

Orientação para leis aplicáveis no Brasil, a relação dos sites das leis aplicáveis. Diretriz para Auditores: A conformidade legal deverá ser verificada: - Conferindo os documentos na propriedade. - Revisando dados sobre conformidade disponíveis publicamente, se houver; - Através de entrevistas com funcionários e partes interessadas e de observações de campo.', '1.1 Toda a legislação local e nacional aplicável é conhecida e cumprida. Nota: Na certificação grupal de fazendas de pequeno porte, os gestores dos grupos devem capacitar os membros em relação às leis aplicáveis e ao cumprimento dos preceitos legais.', TRUE, 1),
('Princípio 1: Cumprimento da Legislação e Boas Práticas Empresariais', '1.1.2', 'As leis aplicáveis estão sendo cumpridas.', 'Imediata', 'Orientação 1.1.1 - 1.1.2 Os produtores precisam ter acesso à informação para saber o que é exigido deles por lei. Exemplos incluem a manutenção de um registo de leis ou acesso à consultoria jurídica relevante. O cumprimento dos preceitos legais deverá ser verificado por meio: • da verificação de dados públicos disponíveis sobre o cumprimento, quando houver; • de entrevistas com funcionários e partes interessadas; e • de observações de campo. A Interpretação Nacional do país correspondente definirá o escopo da verificação da lei aplicável que os produtores precisam cumprir e fornecer evidências do cumprimento durante a auditoria.', '1.1 Toda a legislação local e nacional aplicável é conhecida e cumprida. Nota: Na certificação grupal de fazendas de pequeno porte, os gestores dos grupos devem capacitar os membros em relação às leis aplicáveis e ao cumprimento dos preceitos legais.', TRUE, 2),
('Princípio 1: Cumprimento da Legislação e Boas Práticas Empresariais', '1.1.3', 'Os produtores não devem se envolver em nenhum ato de corrupção, extorsão ou peculato, nem em qualquer forma de suborno - incluindo (mas não limitado a) promessa, oferta, doação ou aceitação de qualquer incentivo monetário indevido ou outro.', 'Curto prazo', 'Orientação 1.1.3 Os grandes produtores devem dispor de sistemas e de uma política por escrito para gerir os riscos de suborno em suas organizações. Os sistemas devem: a. Identificar e monitorar os departamentos da empresa que apresentem alto risco de incidência de suborno. b. Treinar os gestores e funcionários envolvidos sobre as políticas e procedimentos. O sistema também pode incluir: c. Um registro de presentes relevantes recebidos de (e enviados para) terceiros em um livro de presentes, segundo a política da empresa. d. Investigação de quaisquer incidentes de suspeita de suborno dentro da organização. e. Sanções para casos de suborno e tentativa de suborno. A definição de "grandes produtores" será estipulada em nível nacional. Nos países onde já existe legislação relacionada ao assunto, a observância dessas leis será considerada suficiente para o cumprimento deste indicador.', '1.1 Toda a legislação local e nacional aplicável é conhecida e cumprida. Nota: Na certificação grupal de fazendas de pequeno porte, os gestores dos grupos devem capacitar os membros em relação às leis aplicáveis e ao cumprimento dos preceitos legais.', TRUE, 3),
('Princípio 1: Cumprimento da Legislação e Boas Práticas Empresariais', '1.2.1', 'Existem evidências documentais dos direitos de uso da terra (por exemplo, título de propriedade, contrato de arrendamento, ordem judicial, etc.).', 'Imediata', 'Orientação 1.2 Diretriz para Produtores e Auditores: Evidências aceitáveis de direitos legais de uso da terra e métodos adequados para comprovar tais direitos: escrituras, identificação de propriedade rural, contratos de arrendamento, ordem judicial. Quando o proprietário não tiver uma escritura ou identificação de posse e a propriedade estiver sujeita a disputa, a propriedade será certificada apenas depois da conclusão de qualquer processo judiciário vinculado à escritura ou aos direitos de posse da terra ou quando houver uma ordem judicial. Caso haja uma escritura ou uma medida cautelar emitida por um juiz, a última prevalecerá. Caso haja mais de uma escritura ou identificação de posse para a mesma propriedade sob disputa formal, se não houver um mandato judicial, a mencionada propriedade não poderá ser sujeita à certificação.

Orientação: Arrendatários (Meeiros) e contratos de arrendamento A. Uma propriedade que está em arrendamento ou sob regime de meeiro deve cumprir com os critérios da RTRS. B. Quando uma parte da propriedade está em arrendamento ou sob contrato de meeiro, o inquilino será responsável pela inclusão do compromisso do proprietário de regularizar a situação no contrato de arrendamento, de conformidade com os Princípios 4 e 5 Os direitos de uso da terra dos usuários tradicionais da terra estão considerados no Critério 3.2, que deverão ser comparados reciprocamente com este critério.', '1.2 Os direitos de uso da terra estão claramente definidos e são demonstráveis. Nota: Os direitos de uso da terra dos usuários tradicionais da terra são considerados no Critério 3.2, que deve ser cruzado com este Critério.', TRUE, 4),
('Princípio 1: Cumprimento da Legislação e Boas Práticas Empresariais', '1.3.1', 'A partir da avaliação exigida em 4.1.1, foram identificados os aspectos sociais, ambientais e agrícolas da operação (dentro e fora da fazenda) que devem ser melhorados. Nota: Os produtores são livres para escolher os indicadores de melhoria contínua mais relevantes em cada contexto para provar A1:F118que houve melhorias contínuas em relação aos requisitos deste padrão; ex: Teor de carbono do solo, uso de agroquímicos, situação da mata ciliar, etc. O ano usado na linha de base é o ano da primeira avaliação de certificação.', 'Curto prazo', 'Orientação 1.3 Admite-se a possibilidade de que às vezes poderá não haver melhoramento para indicadores específicos de melhoria contínua devido a circunstâncias alheias ao controle do detentor do certificado. Os indicadores de melhoria contínua deverão ser coletados pelo produtor mesmo (a efetividade da quantidade de indicadores encaminhados deverá ser analisada pelo auditor, havendo pelo menos um indicador por cada princípio). Por exemplo, o Princípio 4: A quantidade de APPs (Áreas de Preservação Permanente) restauradas a cada ano está aumentando até alcançar os requisitos legais. Diretriz para Produtores e Auditores: Para a certificação em grupo, o monitoramento em nível de grupo deve ser aplicado quando for considerado apropriado.

Orientação 1.3.1 - 1.3.2 - 1.3.3 Reconhece-se que, às vezes,indicadores específicos de melhoria contínua podem não apresentar melhorias devido a circunstâncias fora do controle do titular do certificado.

Orientação 1.3.1 O produtor irá monitorar e revisar, pelo menos anualmente, 1 indicador por pilar da Folha de Coleta de Dados RTRS para garantir a melhoria contínua. O uso da Folha de Coleta de Dados RTRS serve apenas como orientação para os produtores e seu uso é opcional.', '1.3 Existe uma melhoria contínua em relação aos requisitos deste padrão. Nota: Na certificação grupal, a melhoria contínua pode ser registrada e monitorada para o grupo como um todo.', TRUE, 5),
('Princípio 1: Cumprimento da Legislação e Boas Práticas Empresariais', '1.3.2', 'A partir destes aspectos identificados em 1.3.1, foram selecionados diversos indicadores e definida uma linha de base para possibilitar o monitoramento das melhorias contínuas nos aspectos que deseja-se aprimorar.', 'Imediata', 'Orientação 1.3 Admite-se a possibilidade de que às vezes poderá não haver melhoramento para indicadores específicos de melhoria contínua devido a circunstâncias alheias ao controle do detentor do certificado. Os indicadores de melhoria contínua deverão ser coletados pelo produtor mesmo (a efetividade da quantidade de indicadores encaminhados deverá ser analisada pelo auditor, havendo pelo menos um indicador por cada princípio). Por exemplo, o Princípio 4: A quantidade de APPs (Áreas de Preservação Permanente) restauradas a cada ano está aumentando até alcançar os requisitos legais. Diretriz para Produtores e Auditores: Para a certificação em grupo, o monitoramento em nível de grupo deve ser aplicado quando for considerado apropriado.

Orientação 1.3.1 - 1.3.2 - 1.3.3 Reconhece-se que, às vezes,indicadores específicos de melhoria contínua podem não apresentar melhorias devido a circunstâncias fora do controle do titular do certificado.', '1.3 Existe uma melhoria contínua em relação aos requisitos deste padrão. Nota: Na certificação grupal, a melhoria contínua pode ser registrada e monitorada para o grupo como um todo.', TRUE, 6),
('Princípio 1: Cumprimento da Legislação e Boas Práticas Empresariais', '1.3.3', 'Os resultados do monitoramento são analisados e, quando necessário, a devida ação é planejada e executada para garantir a melhoria contínua', 'Curto prazo', 'Orientação 1.3 Admite-se a possibilidade de que às vezes poderá não haver melhoramento para indicadores específicos de melhoria contínua devido a circunstâncias alheias ao controle do detentor do certificado. Os indicadores de melhoria contínua deverão ser coletados pelo produtor mesmo (a efetividade da quantidade de indicadores encaminhados deverá ser analisada pelo auditor, havendo pelo menos um indicador por cada princípio). Por exemplo, o Princípio 4: A quantidade de APPs (Áreas de Preservação Permanente) restauradas a cada ano está aumentando até alcançar os requisitos legais. Diretriz para Produtores e Auditores: Para a certificação em grupo, o monitoramento em nível de grupo deve ser aplicado quando for considerado apropriado.

Orientação 1.3.1 - 1.3.2 - 1.3.3 Reconhece-se que, às vezes,indicadores específicos de melhoria contínua podem não apresentar melhorias devido a circunstâncias fora do controle do titular do certificado.

Orientação 1.3.3 O monitoramento é feito internamente pelo produtor (gestor do grupo). Um auditor externo analisa os resultados do monitoramento dos processos e verifica as melhorias realizadas.', '1.3 Existe uma melhoria contínua em relação aos requisitos deste padrão. Nota: Na certificação grupal, a melhoria contínua pode ser registrada e monitorada para o grupo como um todo.', TRUE, 7),
('Princípio 2: Condições de trabalho responsáveis', '2.1.1', 'Não é usada qualquer forma de trabalho forçado, compulsório, escravo, traficado ou involuntário em qualquer fase da produção.', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.1 Os funcionários devem ser livres para deixar o local de trabalho depois de cumprir as horas de trabalho; também devem ser livres para rescindir a relação trabalhista, desde que seja dado o devido aviso prévio. Referência: Convenção 29 da OIT sobre Trabalho Forçado e Convenção 105 sobre Abolição do Trabalho Forçado.', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 8),
('Princípio 2: Condições de trabalho responsáveis', '2.1.2', 'Nenhum trabalhador é obrigado a deixar seus documentos de identidade com outras pessoas e nenhuma parte de seu salário, de seus benefícios ou pertences é retida pelo proprietário ou terceiros, a menos que permitido por lei.', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 9),
('Princípio 2: Condições de trabalho responsáveis', '2.1.3', 'Cônjuges e filhos de trabalhadores contratados não são obrigados a trabalhar na fazenda.', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.3 As propriedades agrícolas precisam fornecer uma estrutura adequada para que os filhos e cônjuges possam morar na propriedade e realizar suas atividades pessoais, garantindo uma distância segura de áreas operacionais potencialmente perigosas.', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 10),
('Princípio 2: Condições de trabalho responsáveis', '2.1.4', 'Crianças e menores de 18 anos não devem realizar trabalhos perigosos ou qualquer trabalho que possa pôr em risco sua integridade física ou seu bem-estar mental ou moral.', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.4 - 2.1.5 Agricultura familiar: é permitido o trabalho de menores de 18 anos incompletos e maiores que 13 anos não excedendo a jornada de trabalho de 6 horas diárias desde que não atrapalhe os estudos. As propriedades agrícolas precisam fornecer uma estrutura adequada para que os filhos e cônjuges possam morar na propriedade e realizar suas atividades pessoais, garantindo uma distância segura de áreas operacionais potencialmente perigosas. Agricultura empresarial: é permitido o trabalho mediante a legislação do jovem aprendiz. 2.1.4-2.1.5 2.1.5 A participação em determinadas atividades agrícolas nem sempre é considerada trabalho infantil. Tarefas adequadas à idade - de menor risco e que não interfiram com o estudo e o tempo de lazer das crianças - podem ser uma parte normal do crescimento em ambientes rurais. Especialmente no contexto da agricultura familiar, pecuária e piscicultura de pequeno porte, a participação limitada de crianças em atividades não perigosas pode ser positiva, pois contribui para a transferência intergeracional de competências técnicas e sociais e para a segurança alimentar das crianças. Os jovens envolvidos em alguns aspectos do trabalho agrícola costumam exibir índices mais elevados de autoconfiança, autoestima e competência no trabalho. Portanto, ao considerarem-se as horas e condições de trabalho, a idade, as atividades e os perigos envolvidos, é importante esclarecer a distinção entre tarefas leves - que não causam prejuízos às crianças - e o trabalho infantil, que interfere com o ensino obrigatório e causa danos à saúde e ao desenvolvimento pessoal. 2.1.4-2.1.5 Referência: Convenção 138 da OIT sobre a Idade Mínima e 182 sobre as Piores Formas de Trabalho Infantil.', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 11),
('Princípio 2: Condições de trabalho responsáveis', '2.1.5', 'Crianças menores de 15 anos (ou idade superior, dependendo da legislação nacional) não realizam trabalhos produtivos.', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.4 - 2.1.5 Agricultura familiar: é permitido o trabalho de menores de 18 anos incompletos e maiores que 13 anos não excedendo a jornada de trabalho de 6 horas diárias desde que não atrapalhe os estudos. As propriedades agrícolas precisam fornecer uma estrutura adequada para que os filhos e cônjuges possam morar na propriedade e realizar suas atividades pessoais, garantindo uma distância segura de áreas operacionais potencialmente perigosas. Agricultura empresarial: é permitido o trabalho mediante a legislação do jovem aprendiz. 2.1.4-2.1.5 2.1.5 A participação em determinadas atividades agrícolas nem sempre é considerada trabalho infantil. Tarefas adequadas à idade - de menor risco e que não interfiram com o estudo e o tempo de lazer das crianças - podem ser uma parte normal do crescimento em ambientes rurais. Especialmente no contexto da agricultura familiar, pecuária e piscicultura de pequeno porte, a participação limitada de crianças em atividades não perigosas pode ser positiva, pois contribui para a transferência intergeracional de competências técnicas e sociais e para a segurança alimentar das crianças. Os jovens envolvidos em alguns aspectos do trabalho agrícola costumam exibir índices mais elevados de autoconfiança, autoestima e competência no trabalho. Portanto, ao considerarem-se as horas e condições de trabalho, a idade, as atividades e os perigos envolvidos, é importante esclarecer a distinção entre tarefas leves - que não causam prejuízos às crianças - e o trabalho infantil, que interfere com o ensino obrigatório e causa danos à saúde e ao desenvolvimento pessoal. 2.1.4-2.1.5 Referência: Convenção 138 da OIT sobre a Idade Mínima e 182 sobre as Piores Formas de Trabalho Infantil.', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 12),
('Princípio 2: Condições de trabalho responsáveis', '2.1.6', 'Todos os filhos de colaboradores diretos e residentes na fazenda devem ter acesso a ensino escolar.', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.6 As fazendas garantem que as crianças tenham transporte adequado e material escolar à disposição.', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 13),
('Princípio 2: Condições de trabalho responsáveis', '2.1.7', 'Existe uma política em vigor que ilustra o compromisso da fazenda em não se envolver, apoiar ou tolerar qualquer forma de discriminação.', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.7-2.1.8 A discriminação inclui, mas não se limita a: distinção, exclusão ou preferência que invalide ou prejudique a igualdade de oportunidades ou o tratamento no emprego, seja nos processos de contratação, remuneração, acesso a capacitação, promoção, demissão, realocação horizontal ou aposentadoria, incluindo: a) Etnia, cor, sexo, orientação sexual, gênero, casta, religião, opinião política, origem nacional ou origem social; b) Nacionalidade ou situação migratória; c) Estado civil ou classe social; d) Estado clínico (inclusive soropositividade ou deficiência); e) Situação familiar, incluindo mulheres gestantes e pais com filhos, ou qualquer outra condição protegida pela legislação vigente; f) Ser filiado ou organizador de organizações trabalhistas; g) Ter apresentado queixas por meio dos mecanismos de queixas e reclamações; h) Desigualdade de oportunidades entre os gêneros na nomeação para cargos administrativos; i) Opiniões e convicções políticas, religiosas, sociais, sexuais ou culturais, ou pontos de vista ou afiliações dos trabalhadores. A divergência salarial não é considerada discriminatória quando a empresa tem uma política, de pleno conhecimento dos funcionários, que especifica diferentes escalas de remuneração para níveis de qualificação diversos, tempos de experiência, etc. Referência: Convenção 100 da OIT sobre Igualdade de Remuneração e Convenção 111 da OIT sobre Discriminação.', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 14),
('Princípio 2: Condições de trabalho responsáveis', '2.1.8', 'Pelo mesmo trabalho, todos os trabalhadores recebem remuneração de igual valor, acesso igual a treinamentos e benefícios e oportunidades iguais de promoção e preenchimento de todas as vagas disponíveis. (SALARIO)', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.7-2.1.8 A discriminação inclui, mas não se limita a: distinção, exclusão ou preferência que invalide ou prejudique a igualdade de oportunidades ou o tratamento no emprego, seja nos processos de contratação, remuneração, acesso a capacitação, promoção, demissão, realocação horizontal ou aposentadoria, incluindo: a) Etnia, cor, sexo, orientação sexual, gênero, casta, religião, opinião política, origem nacional ou origem social; b) Nacionalidade ou situação migratória; c) Estado civil ou classe social; d) Estado clínico (inclusive soropositividade ou deficiência); e) Situação familiar, incluindo mulheres gestantes e pais com filhos, ou qualquer outra condição protegida pela legislação vigente; f) Ser filiado ou organizador de organizações trabalhistas; g) Ter apresentado queixas por meio dos mecanismos de queixas e reclamações; h) Desigualdade de oportunidades entre os gêneros na nomeação para cargos administrativos; i) Opiniões e convicções políticas, religiosas, sociais, sexuais ou culturais, ou pontos de vista ou afiliações dos trabalhadores. A divergência salarial não é considerada discriminatória quando a empresa tem uma política, de pleno conhecimento dos funcionários, que especifica diferentes escalas de remuneração para níveis de qualificação diversos, tempos de experiência, etc. Referência: Convenção 100 da OIT sobre Igualdade de Remuneração e Convenção 111 da OIT sobre Discriminação.', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 15),
('Princípio 2: Condições de trabalho responsáveis', '2.1.9', 'Os trabalhadores não são sujeitos à punição corporal, opressão ou coerção mental ou física, abuso verbal ou físico, assédio sexual ou qualquer outro tipo de intimidação. (Entrevista com funcionarios)', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 16),
('Princípio 2: Condições de trabalho responsáveis', '2.1.10', 'Os trabalhadores dispõem de um canal seguro e eficaz para denunciar abusos e garantir que seus direitos sejam respeitados', 'Imediata', 'Orientação 2.1 Devem ser verificados comprovantes dos dados pessoais relevantes dos trabalhadores (por exemplo, sexo e data de nascimento). Os dados coletados devem ser adequados ao local e à legislação em vigor (por exemplo, em alguns países pode não ser adequado - ou mesmo legal - indagar a religião dos funcionários).

Orientação 2.1.10 Existem canais de comunicação abertos e permanentes entre os empregadores e os trabalhadores. (atraves de e-mail ou telefone de alguem que seja imparcial. Deve-se promover o devido tratamento referente a denuncia)', '2.1 Trabalho infantil, trabalho forçado, discriminação e assédio não ocorrem e não recebem apoio. Nota 1: Os requisitos do Princípio 2 aplicam-se tanto aos funcionários diretos quanto a trabalhadores fornecidos por terceiros. O escopo da certificação é a fazenda e seus limites; Precisa ser verificada, portanto, a presença de trabalhadores terceirizados, considerando-se os devidos limites, e os trabalhadores terceirizados contratados para trabalhar na fazenda certificada. Nota 2: Este princípio aplica-se também a trabalhadores migrantes, sazonais e outros trabalhadores contratados. Orientação para o Princípio 2: Em relação ao cumprimento dessas exigências por parte de terceiros (Nota 1): As operações deverão contar com um mecanismo que lhes permita verificar, adequadamente, a conformidade de seus prestadores de serviços. Os auditores devem avaliar o mecanismo de verificação das operações para determinar se os auditores também devem avaliar uma amostra dos prestadores de serviços.', TRUE, 17),
('Princípio 2: Condições de trabalho responsáveis', '2.2.1', 'Os trabalhadores (inclusive trabalhadores temporários), arrendatários, contratados e subcontratados dispõem de um acordo por escrito, num idioma que conseguem compreender e em conformidade com as leis locais.(contrato de trabalho)', 'Imediata', 'Orientação 2.2 O termo ‘trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais. Nos países que não exigem contratos formais de trabalho entre o trabalhador e o empregador, devem ser fornecidos outros comprovantes da relação de trabalho (por exemplo, o registro do empregado junto à previdência social / agência de empregos). A CLT (Consolidação das Leis do Trabalho) permite os acordos tácitos, mas o registro nas CTPS (Carteira de Trabalho e Previdência Social) é considerado necessário.

Orientação 2.2.1 No caso de trabalhadores analfabetos, as orientações das regras locais devem ser seguidas para transmitir o conteúdo do contrato e garantir o pleno entendimento de todas as cláusulas.', '2.2. Os trabalhadores - empregados direta e indiretamente na fazenda - e arrendatários estão devidamente informados e treinados para suas tarefas e cientes de seus direitos e deveres.', TRUE, 18),
('Princípio 2: Condições de trabalho responsáveis', '2.2.2', 'As leis trabalhistas, acordos sindicais ou contratos diretos de emprego, com detalhes sobre os pagamentos e as condições de emprego (por exemplo, horas de trabalho, deduções, horas extras, doença, férias, licença maternidade, razões para demissão, período de aviso prévio, etc.) estão disponíveis em linguagem entendida pelos trabalhadores ou foram explicados cuidadosamente a eles por um gerente ou supervisor. (registro de que todos os direitos do trabalhador lhe foram explicados)', 'Curto prazo', 'Orientação 2.2 O termo ‘trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais. Nos países que não exigem contratos formais de trabalho entre o trabalhador e o empregador, devem ser fornecidos outros comprovantes da relação de trabalho (por exemplo, o registro do empregado junto à previdência social / agência de empregos). A CLT (Consolidação das Leis do Trabalho) permite os acordos tácitos, mas o registro nas CTPS (Carteira de Trabalho e Previdência Social) é considerado necessário.', '2.2. Os trabalhadores - empregados direta e indiretamente na fazenda - e arrendatários estão devidamente informados e treinados para suas tarefas e cientes de seus direitos e deveres.', TRUE, 19),
('Princípio 2: Condições de trabalho responsáveis', '2.2.3', 'Treinamento adequado e apropriado e instruções compreensíveis sobre os direitos fundamentais do trabalho, saúde e segurança - bem como qualquer outra supervisão ou orientação necessária - são proporcionados a todos os trabalhadores. (Ordem de servico, segurança etc)', 'Curto prazo', 'Orientação 2.2 O termo ‘trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais. Nos países que não exigem contratos formais de trabalho entre o trabalhador e o empregador, devem ser fornecidos outros comprovantes da relação de trabalho (por exemplo, o registro do empregado junto à previdência social / agência de empregos). A CLT (Consolidação das Leis do Trabalho) permite os acordos tácitos, mas o registro nas CTPS (Carteira de Trabalho e Previdência Social) é considerado necessário.

Orientação 2.2.3 Se não houver regulamentação sobre a frequência das sessões de formação em saúde e segurança, tal formação deverá ser realizada pelo menos uma vez a cada dois anos ou em maior frequência quando houver mudanças significativas. Eis algumas possíveis situações em que o produtor deve oferecer capacitação (se relevante): • Manuseio, armazenamento e descarte de defensivos agrícolas • Saúde e segurança do trabalho próximo a biodigestores, fossas de esterco, lagoas de efluentes • Escolha de fertilizantes, origem, taxa de aplicação e localização (com base nas características do solo e da cultura agrícola em questão) • Riscos de degradação e perda do solo • Interrupção do desmatamento, perda de biodiversidade e serviços ecossistêmicos • Escassez de energia e água (eficiência energética, sistemas de irrigação sustentáveis, etc.) • Minimização de resíduos, segregação, armazenamento e disposição na fazenda. É elaborado um plano de capacitação para garantir que todos os treinamentos exigidos por lei estejam sempre atualizados e que todos os agricultores e trabalhadores relevantes recebam o treinamento em até 2 anos após a primeira avaliação. Registros dos treinamentos são mantidos com informações desagregadas por gênero sobre os trainees.', '2.2. Os trabalhadores - empregados direta e indiretamente na fazenda - e arrendatários estão devidamente informados e treinados para suas tarefas e cientes de seus direitos e deveres.', TRUE, 20),
('Princípio 2: Condições de trabalho responsáveis', '2.3.1', 'Os produtores e seus funcionários demonstram conhecimento e compreensão das questões de saúde e segurança. (verificado durante a visita do auditor). O funcionario deve saber o passo a passo para retida do EPI.', 'Imediata', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 21),
('Princípio 2: Condições de trabalho responsáveis', '2.3.2', 'Riscos de saúde e segurança relevantes estão identificados, procedimentos para tratar dessas questões são desenvolvidos pelos empregadores e estes são monitorados.', 'Curto prazo', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.

Orientação 2.3.2 Os trabalhadores ou seus representantes (p. ex., sindicatos e / ou grupos de mulheres) devem participar da identificação dos riscos à segurança e proteção e na definição das ações prioritárias.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 22),
('Princípio 2: Condições de trabalho responsáveis', '2.3.3', 'Tarefas potencialmente perigosas são realizadas apenas por pessoas capazes e competentes, sem problemas específicos de saúde. (Verificado os atestados de saude dos funcionarios)', 'Imediata', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.

Orientação 2.3.3 As medidas imediatas são adotadas a fim de parar qualquer operação onde haja perigo iminente e grave para a saúde e a segurança, e para a evacuação apropriada da área. Caso ainda não seja obrigatória por lei, deve ser implementada uma avaliação de risco de segurança e saúde ocupacional para definir quais tipos de trabalho podem ser executados por cada categoria de trabalhadores, bem como seus respectivos riscos.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 23),
('Princípio 2: Condições de trabalho responsáveis', '2.3.4', 'Vestuário e equipamentos de proteção adequados e apropriados são fornecidos e utilizados em todas as operações potencialmente perigosas, como o manuseio e a aplicação de pesticidas e operações manuais ou mecanizadas.', 'Imediata', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.

Orientação 2.3.4 Quando for aplicável, as atividades deverão ser feitas por pessoal devidamente treinado.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 24),
('Princípio 2: Condições de trabalho responsáveis', '2.3.5', 'Existem mecanismos para verificar o cumprimento dos requisitos de segurança pelos trabalhadores.', 'Médio prazo', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.

Orientação 2.3.5 Os funcionários que recebem o EPI (Equipamento de Proteção Individual) deve haver um registro evidenciando o termo de recepção e um compromisso de utilização desse equipamento. Deverá ser mantido um registro desses documentos.

Orientação para todos os critérios: os produtores devem cumprir com a norma regulamentadora NR31. Existe um sistema de advertências, seguidas por sanções permitidas por lei, para os trabalhadores que não cumprirem as exigências de segurança.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 25),
('Princípio 2: Condições de trabalho responsáveis', '2.3.6', 'Há procedimentos em vigor para acidentes e emergências; as instruções são compreendidas claramente por todos os trabalhadores. (documentos, placas de orientação)', 'Curto prazo', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.

Orientação 2.3.6 Os procedimentos em casos de acidentes e emergências devem incluir medidas imediatas para interromper qualquer operação em locais onde há perigo grave e iminente à segurança e a saúde - e, se for o caso, a evacuação do local. Os trabalhadores são treinados neste tema por um profissional qualificado. Não é obrigatório para os pequenos produtores (ver glossário) ter manuais e procedimentos escritos, mas eles devem demonstrar ter conhecimento dos procedimentos de segurança aplicáveis e demonstrar o cumprimento deles.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 26),
('Princípio 2: Condições de trabalho responsáveis', '2.3.7', 'Em caso de acidente ou doença, há primeiros socorros acessíveis e a assistência médica é prestada sem demora.', 'Imediata', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 27),
('Princípio 2: Condições de trabalho responsáveis', '2.3.8', 'Os produtores garantem a manutenção regular das máquinas e equipamentos para garantir sua operação com segurança. (apresentar evidencias de que as maquinas são revisadas com frequencia, ex controle de pontuário) NFE, contrato de serviço de manutenção)', 'Médio prazo', 'Orientação 2.3 Referências: Convenção 155 da OIT sobre Segurança e Saúde dos Trabalhadores; Convenção 184 da OIT sobre Segurança e Saúde na Agricultura; Recomendação 192 da OIT sobre Segurança e Saúde na Agricultura. O meio de verificação utilizado deve ser adequado ao tamanho e à escala da operação. Ex: (2.3.1) Deve haver uma política de saúde e segurança documentada nas operações com funcionários permanentes. Nas fazendas de pequeno porte, isso pode ser demonstrado através de explanações orais. Os produtores devem cumprir com a norma regulamentadora NR31.

Orientação 2.3.8 A manutenção deve seguir as orientações técnicas fornecidas pelos fabricantes e as evidências - como planos de manutenção ou relatórios de serviço - devem ser armazenadas.', '2.3 Um local de trabalho seguro e saudável é garantido a todos os trabalhadores.', TRUE, 28),
('Princípio 2: Condições de trabalho responsáveis', '2.4.1', 'Todos os trabalhadores e arrendatários gozam do direito de estabelecer e / ou filiar-se a uma organização de sua escolha. (Entrevista, os funcionarios precisam demonstrar que estão cientes dessa possibilidade)', 'Imediata', 'Orientação 2.4.1 Referência: Convenção 87 da OIT sobre Liberdade Sindical e Proteção do Direito de Sindicalização.', '2.4 Todos os trabalhadores gozam de liberdade de associação e do direito à negociação coletiva.', TRUE, 29),
('Princípio 2: Condições de trabalho responsáveis', '2.4.2', 'Não é impedido o funcionamento eficaz dessas organizações. Os representantes não são sujeitos à discriminação e têm acesso, sempre que solicitado, a seus afiliados no local de trabalho. (entrevista)', 'Imediata', '', '2.4 Todos os trabalhadores gozam de liberdade de associação e do direito à negociação coletiva.', TRUE, 30),
('Princípio 2: Condições de trabalho responsáveis', '2.4.3', 'Todos os trabalhadores têm o direito à negociação coletiva. (entrevista)', 'Imediata', 'Orientação 2.4.3 Referência Convenção 98 da OIT sobre Direito de Sindicalização e de Negociação Coletiva.', '2.4 Todos os trabalhadores gozam de liberdade de associação e do direito à negociação coletiva.', TRUE, 31),
('Princípio 2: Condições de trabalho responsáveis', '2.4.4', 'Os trabalhadores não são impedidos de interagir com partes externas fora do horário de trabalho (por exemplo, ONGs, sindicatos, inspetores do trabalho, trabalhadores de extensão agrícola, órgãos de certificação). (entrevista)', 'Imediata', '', '2.4 Todos os trabalhadores gozam de liberdade de associação e do direito à negociação coletiva.', TRUE, 32),
('Princípio 2: Condições de trabalho responsáveis', '2.5.1', 'Os salários brutos dos trabalhadores estão em conformidade com a legislação nacional e os acordos setoriais e são pagos, no mínimo, mensalmente.', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.

Orientação 2.5.1 O salário mínimo é definido por acordos sindicais ou, caso não haja esses acordos, pelo salário mínimo nacional em vigor.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 33),
('Princípio 2: Condições de trabalho responsáveis', '2.5.2', 'Não ocorrem deduções salariais de natureza disciplinar, a menos que isso seja permitido pela legislação. As remunerações e benefícios são detalhados e esclarecidos aos trabalhadores; os trabalhadores são pagos de uma maneira que lhes é conveniente. Os salários pagos são registrados pelo empregador. (avaliação do holerite)', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.

Orientação 2.5.2 O critério se aplica a trabalhadores permanentes e sazonais envolvidos na produção agrícola.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 34),
('Princípio 2: Condições de trabalho responsáveis', '2.5.3', 'A jornada normal de trabalho não ultrapassa 48 horas semanais. As horas extras não excedem 12 horas semanais.', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.

Orientação 2.5.3 O período de trabalho no Brasil é de 44 horas por semana. As horas-extras semanais não excedem 12 horas e devem ser horas-extras eventuais.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 35),
('Princípio 2: Condições de trabalho responsáveis', '2.5.4', 'Se forem necessárias horas-extras adicionais, as seguintes condições devem ser cumpridas: a) Elas só ocorrem em períodos limitados de tempo (por exemplo, no pico da colheita, na época de plantio). b) Caso haja um sindicato ou organização representativa, as condições das horas extras são negociadas e acordadas com a organização. c) Quando não houver sindicato ou acordo com organização representativa, a média de horas de trabalho no período de dois meses após o início do período excepcional não deve exceder 60 horas semanais.', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 36),
('Princípio 2: Condições de trabalho responsáveis', '2.5.5', 'As horas trabalhadas pelos funcionários são registradas pelo empregador. No caso de trabalhadores indiretos, as horas de trabalho serão registradas quando possível. (obrigatoriamente é exigida a folha de registro das horas)', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.

Orientação 2.5.5-2.5.6 Referência: Convenção 1 da OIT sobre Horas de Trabalho.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 37),
('Princípio 2: Condições de trabalho responsáveis', '2.5.6', 'O trabalho extraordinário é sempre voluntário e pago de acordo com a lei ou com as normas do setor. Quando são necessárias horas extras de trabalho, os trabalhadores recebem notificação oportuna. Os trabalhadores têm direito a, pelo menos, um dia de folga a cada seis dias consecutivos de trabalho. (entrevista com os funcionários, ou evidencia documental).', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.

Orientação 2.5.5-2.5.6 Referência: Convenção 1 da OIT sobre Horas de Trabalho.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 38),
('Princípio 2: Condições de trabalho responsáveis', '2.5.7', 'Quanto à maternidade, as trabalhadoras assalariadas gozam de todos os direitos e proteções previstos nas práticas e leis nacionais. As trabalhadoras em licença maternidade têm o direito de regressar a seus postos de trabalho sob os mesmos termos e condições vigentes antes da licença. Elas não são sujeitas a qualquer tipo de discriminação, perda de posição ou redução salarial. (é verificado se ha mulheres com linceça maternidade, entrevista) Caso nao volte a atividade é legal um pedido de recisão.', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 39),
('Princípio 2: Condições de trabalho responsáveis', '2.5.8', 'Se os trabalhadores são pagos por resultados, um dia de trabalho normal de 8 horas possibilita que os trabalhadores (homens e mulheres) recebam, pelo menos, o salário mínimo definido nacionalmente ou pelo setor. (é verificado o pagamento de homens e mulheres)', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 40),
('Princípio 2: Condições de trabalho responsáveis', '2.5.9', 'Todos os funcionários recebem água potável na fazenda. Se os funcionários vivem na fazenda, eles também têm acesso a habitação e alimentos a preços acessíveis e adequados, além de banheiros e locais para lavar as mãos. Quando esses serviços são cobrados, os valores estão alinhados com as condições de mercado. Os alojamentos são seguros e dispõem, no mínimo, de saneamento básico. (é avaliado as condições do alojamento, qualidade da agua, refeitorio etc)', 'Imediata', 'Orientação 2.5 ‘Trabalhadores indiretamente empregados na fazenda'' refere-se, aqui, aos funcionários de prestadores de serviços que realizam serviços diretamente relacionados ao processo de produção. O escopo dos ''serviços diretamente relacionados ao processo de produção'' será definido nas interpretações nacionais.

Orientação 2.5.9 É exigido a análise da potabilidade da água oferecida aos funcionários pelo menos uma vez ao ano.', '2.5 Todos os trabalhadores da fazenda, empregados direta ou indiretamente, têm remuneração, no mínimo, igual ao valor previsto na legislação nacional e em acordos setoriais.', TRUE, 41),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.1.2', 'As comunidades locais foram informadas dos canais de comunicação, que possibilitam que as comunicações sejam anônimas (se assim desejado).(pode enviar as comunidades um memorando refentes aos canais de comunicação) (é feito o teste pelo auditor) deve se saber quem recebe, registra e trata do assunto. pode criar um caderno de registro de comunicação.', 'Curto prazo', 'Orientação 3.1 Os canais de comunicação para envio de queixas e reclamações devem usar idiomas locais e meios adequados (por exemplo, a Internet não é um mecanismo adequado de comunicação com comunidades que não têm acessoà web). Os requisitos de comunicação devem ser adequados para a identificação de quaisquer disputas com os usuários tradicionais das terras, conforme referido no Critério 3.2 Nos casos em que ficar demonstrado que as pessoas na propriedade (ou ao lado dela) estão lá ilegalmente (por exemplo, posseiros), os produtores devem tentar estabelecer comunicação, mas não são obrigados manter um diálogo. As comunidades locais e outros groupos privados de direitos podem ser representados por representantes legítimos em casos de comunicação ou negociação ou em situações de auditoria. Quando isto ocorrer, o produtor ou auditor não está isento da responsabilidade de comunicar-se com outros membros da comunidade - especialmente os pobres, analfabetos, jovens, mulheres ou grupos indígenas. As evidências de cumprimento deste indicador podem ser as notificações enviadas a vizinhos e comunidades locais adjacentes. É importante incluir entrevistas com membros da comunidade para avaliar a existência de canais de comunicação e sua adequação.

Orientação 3.1.2 As evidências de cumprimento deste indicador podem ser notificações apresentadas aos vizinhos e às comunidades locais adjacentes. Alguns exemplos (não exaustivos) de canais de comunicação: comunicação de informações a terceiros, incluindo a pessoa de contato na fazenda, o número de telefone e / ou e-mail, etc.).', '3.1 Há canais disponíveis para comunicação e diálogo com a comunidade local (incluindo povos indígenas) sobre temas relacionados às atividades da fazenda produtora de soja e seus impactos. Nota: Dessa forma, eles participarão de forma efetiva e significativa nas decisões sobre assuntos que os afetam. (Divulgação de 2 ou mais canais de comunicação diferentes, ex e-mail, telefone, na guarita de acesso a fazenda)', TRUE, 42),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.2.1', 'Em caso de disputa relativa aos direitos de uso; é realizada uma avaliação abrangente, participativa e documentada dos direitos da comunidade. (caso tenha uma decisão judicial e o estudo de ganho de causa do produtor)', 'Imediata', 'Orientação 3.2 Ao se candidatarem à certificação, os produtores identificarão as comunidades locais e os usuários tradicionais da terra. Os usuários tradicionais da terra apresentarão comprovação razoável de que vêm exercendo o direito de uso ou acesso à área ou aos serviços ecossistêmicos derivados da área nos últimos dez anos, antes de maio de 2009. Provas razoáveis podem basear-se em critérios específicos e diretamente relevantes às suas finalidades (por exemplo: documentos oficiais / timbrados válidos / atualizados, reconhecidos por funcionários e empregadores). No caso de comunidades indígenas tradicionais, também se aplicam os artigos 14-18 da Convenção 169 da OIT. Os usuários tradicionais da terra podem ser representados por representantes legítimos para fins de comunicação, negociação ou auditoria. Quando isto ocorrer, o produtor ou auditor não está isento da responsabilidade de comunicarse com outros membros da comunidade.

Orientação 3.2.1 A avaliação dos direitos da comunidade deve buscar: a) identificar os direitos e usos individuais e coletivos das comunidades locais e usuários tradicionais das terras; e b) identificar os usos dos recursos hídricos (se houver); c) identificar os locais e as condições paisagísticas necessárias para garantir o cumprimento desses direitos; d) identificar os locais / questões onde há conflitos entre os direitos de propriedade e os direitos de uso tradicional da terra e de serviços ecossistêmicos; e) encontrar uma solução para resolver possíveis conflitos no uso da terra e / ou chegar a um acordo quanto à proposta de compensação. Sempre que houver decisões transitadas em julgado, os termos da decisão serão respeitados. Caso ocorra um processo contencioso, enquanto ele estiver sub judice (em litígio, pendente de decisão), isso não impedirá o acesso à certificação, desde que sejam observadas as orientações determinadas pelo juiz. Na ausência de tais orientações, os usuários tradicionais das terras poderão continuar a exercer os seus direitos até que o caso seja resolvido.', '3.2 Em áreas com usuários tradicionais das terras, incluindo povos indígenas, os usos conflitantes da terra são evitados ou resolvidos.', TRUE, 43),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.2.2', 'Nos casos em que os usuários tradicionais das terras abrem mão de seus direitos, há evidências documentais de que as comunidades afetadas receberam compensação e deram consentimento livre, prévio, informado e documentado.', 'Imediata', 'Orientação 3.2 Ao se candidatarem à certificação, os produtores identificarão as comunidades locais e os usuários tradicionais da terra. Os usuários tradicionais da terra apresentarão comprovação razoável de que vêm exercendo o direito de uso ou acesso à área ou aos serviços ecossistêmicos derivados da área nos últimos dez anos, antes de maio de 2009. Provas razoáveis podem basear-se em critérios específicos e diretamente relevantes às suas finalidades (por exemplo: documentos oficiais / timbrados válidos / atualizados, reconhecidos por funcionários e empregadores). No caso de comunidades indígenas tradicionais, também se aplicam os artigos 14-18 da Convenção 169 da OIT. Os usuários tradicionais da terra podem ser representados por representantes legítimos para fins de comunicação, negociação ou auditoria. Quando isto ocorrer, o produtor ou auditor não está isento da responsabilidade de comunicarse com outros membros da comunidade.', '3.2 Em áreas com usuários tradicionais das terras, incluindo povos indígenas, os usos conflitantes da terra são evitados ou resolvidos.', TRUE, 44),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.2.3', 'Os produtores devem respeitar os direitos, costumes e culturas dos povos indígenas, nos termos da Declaração das Nações Unidas sobre os Direitos dos Povos Indígenas (2007) e da Convenção 169 da OIT (1989). (o produtor precisa demonstrar de que ele respeita)', 'Imediata', 'Orientação 3.2 Ao se candidatarem à certificação, os produtores identificarão as comunidades locais e os usuários tradicionais da terra. Os usuários tradicionais da terra apresentarão comprovação razoável de que vêm exercendo o direito de uso ou acesso à área ou aos serviços ecossistêmicos derivados da área nos últimos dez anos, antes de maio de 2009. Provas razoáveis podem basear-se em critérios específicos e diretamente relevantes às suas finalidades (por exemplo: documentos oficiais / timbrados válidos / atualizados, reconhecidos por funcionários e empregadores). No caso de comunidades indígenas tradicionais, também se aplicam os artigos 14-18 da Convenção 169 da OIT. Os usuários tradicionais da terra podem ser representados por representantes legítimos para fins de comunicação, negociação ou auditoria. Quando isto ocorrer, o produtor ou auditor não está isento da responsabilidade de comunicarse com outros membros da comunidade.

Orientação 3.2.3 Verificado por meio da consulta pública', '3.2 Em áreas com usuários tradicionais das terras, incluindo povos indígenas, os usos conflitantes da terra são evitados ou resolvidos.', TRUE, 45),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.2.4', 'Locais de importância cultural, ecológica, econômica ou religiosa e recursos fundamentais para satisfazer as necessidades básicas das comunidades locais e dos povos indígenas (de subsistência, saúde, nutrição, água, etc.) devem ser identificados claramente em conjunto com os grupos em questão, bem como reconhecidos e protegidos pelos gestores de fazenda. ( o que o produtor faz para proteger)', 'Imediata', 'Orientação 3.2 Ao se candidatarem à certificação, os produtores identificarão as comunidades locais e os usuários tradicionais da terra. Os usuários tradicionais da terra apresentarão comprovação razoável de que vêm exercendo o direito de uso ou acesso à área ou aos serviços ecossistêmicos derivados da área nos últimos dez anos, antes de maio de 2009. Provas razoáveis podem basear-se em critérios específicos e diretamente relevantes às suas finalidades (por exemplo: documentos oficiais / timbrados válidos / atualizados, reconhecidos por funcionários e empregadores). No caso de comunidades indígenas tradicionais, também se aplicam os artigos 14-18 da Convenção 169 da OIT. Os usuários tradicionais da terra podem ser representados por representantes legítimos para fins de comunicação, negociação ou auditoria. Quando isto ocorrer, o produtor ou auditor não está isento da responsabilidade de comunicarse com outros membros da comunidade.

Orientação 3.2.4 Conforme determinação da Funai, quando o processo de reconhecimento de terra indígena estiver na fase de homologação ou posterior, não atende ao critério. Entende-se por Comunidade local, comunidade tradicional, conforme legislação.', '3.2 Em áreas com usuários tradicionais das terras, incluindo povos indígenas, os usos conflitantes da terra são evitados ou resolvidos.', TRUE, 46),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.3.1', 'As evidências documentais sobre as reclamações e queixas são recebidas e mantidas.(precisa de uma metodologia, ex caderno de registro)', 'Imediata', 'Orientação 3.3.1 Reclamações anônimas também serão tratadas.', '3.3 Um mecanismo de reclamações e queixas está implantado e é acessível à comunidade local (incluindo povos indígenas), os funcionários e aos usuários tradicionais das terras. Nota: Na certificação grupal, o mecanismo de queixas e reclamações pode ser administrado pelo gestor do grupo e os registros das queixas e reclamações podem ser mantidos para o grupo como um todo.', TRUE, 47),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.3.2', 'Todas as reclamações e queixas recebidas são tratadas adequadamente e em tempo hábil.', 'Imediata', 'Orientação 3.3.2 Se o produtor receber uma reclamação, ele é obrigado a enviar uma resposta no prazo de 30 dias do recebimento da reclamação para acusar seu recebimento e / ou começar a resolver a questão.', '3.3 Um mecanismo de reclamações e queixas está implantado e é acessível à comunidade local (incluindo povos indígenas), os funcionários e aos usuários tradicionais das terras. Nota: Na certificação grupal, o mecanismo de queixas e reclamações pode ser administrado pelo gestor do grupo e os registros das queixas e reclamações podem ser mantidos para o grupo como um todo.', TRUE, 48),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.4.1', 'As oportunidades de emprego são divulgadas localmente. (print de tela de instagram, ou outro meio. Precisa ser comprovado)', 'Curto prazo', 'Orientação 3.4.1 As evidências podem incluir registros sobre a proporção de funcionários locais empregados na fazenda.', '3.4 São oferecidas oportunidades justas de emprego e fornecimento de bens e serviços à população local, independentemente de sexo ou raça.', TRUE, 49),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.4.2', 'Sempre que possível, há colaboração com programas de formação direcionados à população local (incluindo, por exemplo, povos indígenas). (necessario guardar o registro de vagas que foram disponibilizados para pessoas de fora. Ex lista de presença).', 'Médio prazo', 'Orientação 3.4.2 Se não for possível aplicar este indicador, deve ser apresentada uma justificativa ao auditor. Quando não haja população na vizinhança da fazenda, o termo população local se referirá à população no distrito municipal próximo.', '3.4 São oferecidas oportunidades justas de emprego e fornecimento de bens e serviços à população local, independentemente de sexo ou raça.', TRUE, 50),
('Princípio 3: Relações Responsáveis com a Comunidade', '3.4.3', 'Oportunidades relativas à oferta de bens e serviços são oferecidas à população local.', 'Médio prazo', 'Orientação 3.4.3 Refere-se aos bens e serviços centrais às atividades de produção. As evidências incluem orçamentos de serviços recebidos de fornecedores locais. Quando não haja população na vizinhança da fazenda, o termo população local se referirá à população no distrito municipal próximo.', '3.4 São oferecidas oportunidades justas de emprego e fornecimento de bens e serviços à população local, independentemente de sexo ou raça.', TRUE, 51),
('Princípio 4: Responsabilidade Ambiental', '4.1.1', 'É realizada uma avaliação social e de certificação 16 (ver também o Indicador 1.3.1). Essa avaliação precisa ser refeita antes das operações serem ampliadas. ambiental inicial antes da primeira auditoria. (precisa ser avaliada por pessoa treinada e com experiencia na area)', 'Imediata', 'Orientação 4.1 A avaliação deve ser adequada à escala da operação, considerando apenas os impactos significativos e relevantes à atividade. Na certificação grupal de pequenos produtores, grupos distintos localizados em áreas semelhantes e que enfrentam questões semelhantes podem trocar informações ao preparar e / ou realizar a avaliação. No entanto, os relatórios devem ser elaborados para o grupo como um todo. Se houver requisitos nacionais referentes às avaliações de impacto e adequados ao cumprimento deste Critério (identificados pelo GTN), estes requisitos devem ser seguidos. Quando não houver requisitos nacionais, os auditores devem verificar se foi seguido um processo adequado (por exemplo, “Avaliação de aspectos e impactos baseados na ISO 14.001”) A avaliação deve ser feita no início da operação ou sempre que houver mudança significativa no procedimento da fazenda.

Orientação 4.1.1 Esta avaliação deve identificar as espécies endêmicas, raras, ameaçadas ou em perigo (ver também indicador 4.5.3).', '4.1 Os impactos sociais e ambientais dentro e fora do local foram avaliados e foram tomadas as medidas adequadas para minimizar e mitigar quaisquer impactos negativos. Nota: Na certificação grupal de pequenas fazendas, os Indicadores 4.1.1, 4.1.2, 4.1.3, 4.1.4 e 4.1.5 podem fazer parte do SCI em nível grupal e também podem ser cumpridos em grupo.', TRUE, 52),
('Princípio 4: Responsabilidade Ambiental', '4.1.2', 'A avaliação é realizada por uma pessoa adequadamente treinada e experiente nesta tarefa.', 'Imediata', 'Orientação 4.1 A avaliação deve ser adequada à escala da operação, considerando apenas os impactos significativos e relevantes à atividade. Na certificação grupal de pequenos produtores, grupos distintos localizados em áreas semelhantes e que enfrentam questões semelhantes podem trocar informações ao preparar e / ou realizar a avaliação. No entanto, os relatórios devem ser elaborados para o grupo como um todo. Se houver requisitos nacionais referentes às avaliações de impacto e adequados ao cumprimento deste Critério (identificados pelo GTN), estes requisitos devem ser seguidos. Quando não houver requisitos nacionais, os auditores devem verificar se foi seguido um processo adequado (por exemplo, “Avaliação de aspectos e impactos baseados na ISO 14.001”) A avaliação deve ser feita no início da operação ou sempre que houver mudança significativa no procedimento da fazenda.

Orientação 4.1.2 Recomenda-se a inclusão de consultas com as partes interessadas e abordagens participativas no processo de avaliação.', '4.1 Os impactos sociais e ambientais dentro e fora do local foram avaliados e foram tomadas as medidas adequadas para minimizar e mitigar quaisquer impactos negativos. Nota: Na certificação grupal de pequenas fazendas, os Indicadores 4.1.1, 4.1.2, 4.1.3, 4.1.4 e 4.1.5 podem fazer parte do SCI em nível grupal e também podem ser cumpridos em grupo.', TRUE, 53),
('Princípio 4: Responsabilidade Ambiental', '4.1.3', 'A avaliação é realizada de forma abrangente e transparente.', 'Imediata', 'Orientação 4.1 A avaliação deve ser adequada à escala da operação, considerando apenas os impactos significativos e relevantes à atividade. Na certificação grupal de pequenos produtores, grupos distintos localizados em áreas semelhantes e que enfrentam questões semelhantes podem trocar informações ao preparar e / ou realizar a avaliação. No entanto, os relatórios devem ser elaborados para o grupo como um todo. Se houver requisitos nacionais referentes às avaliações de impacto e adequados ao cumprimento deste Critério (identificados pelo GTN), estes requisitos devem ser seguidos. Quando não houver requisitos nacionais, os auditores devem verificar se foi seguido um processo adequado (por exemplo, “Avaliação de aspectos e impactos baseados na ISO 14.001”) A avaliação deve ser feita no início da operação ou sempre que houver mudança significativa no procedimento da fazenda.', '4.1 Os impactos sociais e ambientais dentro e fora do local foram avaliados e foram tomadas as medidas adequadas para minimizar e mitigar quaisquer impactos negativos. Nota: Na certificação grupal de pequenas fazendas, os Indicadores 4.1.1, 4.1.2, 4.1.3, 4.1.4 e 4.1.5 podem fazer parte do SCI em nível grupal e também podem ser cumpridos em grupo.', TRUE, 54),
('Princípio 4: Responsabilidade Ambiental', '4.1.4', 'As medidas para minimizar ou mitigar os impactos identificados pela avaliação estão sendo documentadas, implementadas e monitoradas.', 'Curto prazo', 'Orientação 4.1 A avaliação deve ser adequada à escala da operação, considerando apenas os impactos significativos e relevantes à atividade. Na certificação grupal de pequenos produtores, grupos distintos localizados em áreas semelhantes e que enfrentam questões semelhantes podem trocar informações ao preparar e / ou realizar a avaliação. No entanto, os relatórios devem ser elaborados para o grupo como um todo. Se houver requisitos nacionais referentes às avaliações de impacto e adequados ao cumprimento deste Critério (identificados pelo GTN), estes requisitos devem ser seguidos. Quando não houver requisitos nacionais, os auditores devem verificar se foi seguido um processo adequado (por exemplo, “Avaliação de aspectos e impactos baseados na ISO 14.001”) A avaliação deve ser feita no início da operação ou sempre que houver mudança significativa no procedimento da fazenda.

Orientação 4.1.4 Para evitar impactos, a recomendação é seguir a regra “Evitar, minimizar, restaurar” e compensar os impactos, priorizando a prevenção dos impactos antes que eles precisem ser remediados.', '4.1 Os impactos sociais e ambientais dentro e fora do local foram avaliados e foram tomadas as medidas adequadas para minimizar e mitigar quaisquer impactos negativos. Nota: Na certificação grupal de pequenas fazendas, os Indicadores 4.1.1, 4.1.2, 4.1.3, 4.1.4 e 4.1.5 podem fazer parte do SCI em nível grupal e também podem ser cumpridos em grupo.', TRUE, 55),
('Princípio 4: Responsabilidade Ambiental', '4.1.5', 'Um resumo do relatório de avaliação social e ambiental deve ser disponibilizado mediante solicitação.(precisa abordar todos os critérios, conclusoes de cada criterio....)', 'Imediata', 'Orientação 4.1 A avaliação deve ser adequada à escala da operação, considerando apenas os impactos significativos e relevantes à atividade. Na certificação grupal de pequenos produtores, grupos distintos localizados em áreas semelhantes e que enfrentam questões semelhantes podem trocar informações ao preparar e / ou realizar a avaliação. No entanto, os relatórios devem ser elaborados para o grupo como um todo. Se houver requisitos nacionais referentes às avaliações de impacto e adequados ao cumprimento deste Critério (identificados pelo GTN), estes requisitos devem ser seguidos. Quando não houver requisitos nacionais, os auditores devem verificar se foi seguido um processo adequado (por exemplo, “Avaliação de aspectos e impactos baseados na ISO 14.001”) A avaliação deve ser feita no início da operação ou sempre que houver mudança significativa no procedimento da fazenda.', '4.1 Os impactos sociais e ambientais dentro e fora do local foram avaliados e foram tomadas as medidas adequadas para minimizar e mitigar quaisquer impactos negativos. Nota: Na certificação grupal de pequenas fazendas, os Indicadores 4.1.1, 4.1.2, 4.1.3, 4.1.4 e 4.1.5 podem fazer parte do SCI em nível grupal e também podem ser cumpridos em grupo.', TRUE, 56),
('Princípio 4: Responsabilidade Ambiental', '4.2.1', 'Não há queimadas em qualquer parte da propriedade, seja de resíduos vegetais, dejetos ou para a limpeza da vegetação. (comprovanntes do orgão ambiental)', 'Imediata', 'Orientação 4.2.1 Esta regra tem três exceções: a) quando existir a obrigação legal de realizar-se a queimada como medida sanitária; b) quando ela é usada como combustível para a secagem de safras; c) contra incêndios ou para combater incêndios', '4.2 A poluição é minimizada e os resíduos da produção são geridos de forma responsável.', TRUE, 57),
('Princípio 4: Responsabilidade Ambiental', '4.2.2', 'Todos os resíduos são armazenados e descartados de forma adequada (por exemplo, combustíveis, baterias, pneus, lubrificantes, esgoto).', 'Imediata', 'Orientação 4.2.2 Ter em conta a política nacional de resíduos sólidos (lei nacional) e NBR 10007. Se houver regras nacionais sobre o armazenamento e descarte seguros de diferentes tipos de resíduos perigosos, elas devem ser obedecidas. Se não houver exigências regulamentares, deve-se buscar orientações sobre as melhores opções disponíveis e ouvir recomendações. Todas as áreas de eliminação de resíduos e compostagem na fazenda (por exemplo, para resíduos domésticos) devem estar a uma distância segura das áreas de convivência e / ou hidrovias. Devem ser adotadas medidas para garantir que a fazenda esteja limpa e em ordem. Resíduos de plástico e outros resíduos não devem ser deixados nos campos, nas margens dos campos, ao redor da fazenda ou à beira das estradas. Os agricultores e trabalhadores não devem jogar lixo e outros resíduos gerais em valas, córregos ou poços. A gestão de resíduos deve ocorrer na fase de produção por meio da gestão, armazenamento, transporte e disposição dos fluxos de resíduos; não deve haver qualquer aterro ou despejo não controlado de resíduos em áreas não oficialmente designadas como aterros. A fazenda deve ter um procedimento definido para tratar de incidentes de poluição e mitigar possíveis danos decorrentes de contaminações e vazamentos.', '4.2 A poluição é minimizada e os resíduos da produção são geridos de forma responsável.', TRUE, 58),
('Princípio 4: Responsabilidade Ambiental', '4.2.3', 'Há estruturas adequadas para evitar derramamentos de óleo e outros poluentes.', 'Curto prazo', '', '4.2 A poluição é minimizada e os resíduos da produção são geridos de forma responsável.', TRUE, 59),
('Princípio 4: Responsabilidade Ambiental', '4.2.4', 'O reuso e a reciclagem ocorrem sempre que possível. (observação visual, ex utiliza coletores de residuos de acordo com a classe, estrutura de aproveitamento. Observação documental, ex documento de entrega para empresas coletoras)', 'Médio prazo', 'Orientação 4.2.4 Há descarte de resíduos adequado (quando não houver reutilização / reciclagem) e áreas de armazenagem de resíduos na fazenda e sua localização será conforme as leis aplicáveis (no Princípio 5, é mencionada a limpeza de embalagens de agroquímicos e de pulverizadores). Programas de reciclagem: O INPEV é o Instituto Nacional de Processamento de Embalagens Vazias. Trata- se de uma organização sem fins lucrativos que representa à Indústria de Proteção de Cultivos na sua responsabilidade de fornecer a disposição correta de embalagens vazias de produtos para a proteção de cultivos. O site é: http://www.inpev.org.br/ O produtor deve adotar práticas de Economia Circular ou explicar por que não aplica a reciclagem, caso não a utilize e em casos em que seria fácil fazê-la.', '4.2 A poluição é minimizada e os resíduos da produção são geridos de forma responsável.', TRUE, 60),
('Princípio 4: Responsabilidade Ambiental', '4.2.5', 'Existe um plano de gestão de resíduos, incluindo todas as áreas da propriedade.', 'Curto prazo', 'Orientação 4.2.5 Os resíduos incluem resíduos sólidos não orgânicos e orgânicos, bem como águas residuais resultantes da operação (p. ex., para a limpeza de equipamentos e tanques). No caso de grandes e médios produtores, isto deve ser documentado. Nas fazendas de pequeno porte ou familiares, os produtores só precisam saber quais resíduos são gerados em suas propriedades e o que é feito com cada um deles. Deve-se descrever o tipo, a quantidade e o destino dos resíduos. Referência: Lei 12.305/2010 (Lei Ordinária), Política Nacional de Resíduos Sólidos Nota para Produtores e Auditores: 1. O uso e a disposição de agroquímicos é tratado no Princípio 5. 2. No caso do ponto 4.2.5, para pequenos produtores e produtores familiares, o plano de manejo de resíduos pode ser feito em grupos. 3. As atividades do plano de manejo de resíduos devem ser de acordo aos tipos e às quantidades dos resíduos gerados.', '4.2 A poluição é minimizada e os resíduos da produção são geridos de forma responsável.', TRUE, 61),
('Princípio 4: Responsabilidade Ambiental', '4.3.1', 'É registrado o uso total e direto de combustíveis fósseis ao longo do tempo; o volume por hectare e por unidade de produto é monitorado em todas as atividades relacionadas à produção de soja.(registro necessario desde o prmeiro ano, é fundamental para liberar a certificação na plataforma)', 'Médio prazo', 'Orientação 4.3 O produtor deverá elaborar um plano que demonstre como cumprirá este critério. O plano deve mostrar as metas (redução de % e até quando) que o produtor definiu para cada área e quais medidas irá tomar para atingi-las.

Orientação 4.3.1 Em fazendas produtoras de diversas culturas, deve ser feita uma estimativa do uso de combustíveis fósseis na produção da soja. As ''atividades relacionadas à produção de soja'' incluem: operações de campo e transporte na fazenda, realizadas tanto pelo produtor como por terceiros.', '4.3 Há esforços para reduzir as emissões e aumentar o sequestro de Gases de Efeito Estufa (GEE) na fazenda. Nota: Outras questões relevantes às emissões de GEE são abordadas em outros princípios, incluindo: Uso de fertilizantes (Critério 5.5), Mudança no uso da terra (Critério 4.4). Solicita ações do produtor para sequestro de carbono, ex reflorestamento, adubo verde etc. Tudo deve estar documentado em um plano. A evidencia pode ser comprovada pela visita a campo pelo auditor.', TRUE, 62),
('Princípio 4: Responsabilidade Ambiental', '4.3.2', 'Se ocorre um aumento da intensidade do uso de combustíveis fósseis, esse aumento é justificado. Se não houver justificativa, existe um plano de ação para reduzir o uso. (medido após o segundo ano)', 'Médio prazo', 'Orientação 4.3 O produtor deverá elaborar um plano que demonstre como cumprirá este critério. O plano deve mostrar as metas (redução de % e até quando) que o produtor definiu para cada área e quais medidas irá tomar para atingi-las.

Orientação 4.3.2 Podem ocorrer oscilações anuais na intensidade do uso de combustíveis fósseis, devido a variações naturais de produtividade. Essa tendência deve ser monitorada por um período de vários anos. Um exemplo de justificativa do aumento da intensidade do uso de combustíveis fósseis pode ser quando uma plantação é perdida devido à seca e precisa ser reiniciada. O uso de energias renováveis (biocombustíveis, biogás, energia solar e eólica etc.) é incentivado na fazenda. No caso da substituição da eletricidade por energias renováveis, deve ser quantificada a economia equivalente ao uso de combustíveis fósseis.', '4.3 Há esforços para reduzir as emissões e aumentar o sequestro de Gases de Efeito Estufa (GEE) na fazenda. Nota: Outras questões relevantes às emissões de GEE são abordadas em outros princípios, incluindo: Uso de fertilizantes (Critério 5.5), Mudança no uso da terra (Critério 4.4). Solicita ações do produtor para sequestro de carbono, ex reflorestamento, adubo verde etc. Tudo deve estar documentado em um plano. A evidencia pode ser comprovada pela visita a campo pelo auditor.', TRUE, 63),
('Princípio 4: Responsabilidade Ambiental', '4.3.3', 'A matéria orgânica no solo é monitorada para quantificar as mudanças do carbono no solo; são tomadas medidas para melhorar ou, no mínimo, mitigar as tendências negativas. (análise de solo, MO)', 'Médio prazo', 'Orientação 4.3 O produtor deverá elaborar um plano que demonstre como cumprirá este critério. O plano deve mostrar as metas (redução de % e até quando) que o produtor definiu para cada área e quais medidas irá tomar para atingi-las.', '4.3 Há esforços para reduzir as emissões e aumentar o sequestro de Gases de Efeito Estufa (GEE) na fazenda. Nota: Outras questões relevantes às emissões de GEE são abordadas em outros princípios, incluindo: Uso de fertilizantes (Critério 5.5), Mudança no uso da terra (Critério 4.4). Solicita ações do produtor para sequestro de carbono, ex reflorestamento, adubo verde etc. Tudo deve estar documentado em um plano. A evidencia pode ser comprovada pela visita a campo pelo auditor.', TRUE, 64),
('Princípio 4: Responsabilidade Ambiental', '4.3.4', 'São identificadas e, quando possível, implementadas oportunidades de aumentar-se o sequestro de carbono através da restauração da vegetação nativa, de plantações florestais e outros meios.(Pode ser vivero que serão podruzidas dentro da propiedade e fornecidas para reflorestamento).', 'Médio prazo', 'Orientação 4.3 O produtor deverá elaborar um plano que demonstre como cumprirá este critério. O plano deve mostrar as metas (redução de % e até quando) que o produtor definiu para cada área e quais medidas irá tomar para atingi-las.

Orientação 4.3.4 Se os produtores não puderem implementar as oportunidades identificadas para aumentar o sequestro de carbono, deve ser apresentada uma justificativa ao auditor. Outros meios podem incluir: • Restaurar passivamente as cercas e beiras das estradas • Plantar florestas • Culturas de cobertura em áreas não produtivas e degradadas, bem como várzeas ou planícies. • Conservação de plantações não nativas que antes eram usadas como sombreamento para gado', '4.3 Há esforços para reduzir as emissões e aumentar o sequestro de Gases de Efeito Estufa (GEE) na fazenda. Nota: Outras questões relevantes às emissões de GEE são abordadas em outros princípios, incluindo: Uso de fertilizantes (Critério 5.5), Mudança no uso da terra (Critério 4.4). Solicita ações do produtor para sequestro de carbono, ex reflorestamento, adubo verde etc. Tudo deve estar documentado em um plano. A evidencia pode ser comprovada pela visita a campo pelo auditor.', TRUE, 65),
('Princípio 4: Responsabilidade Ambiental', '4.4.1', 'A partir de maio de 2009, não houve limpeza ou conversão das seguintes áreas:', 'Imediata', 'Orientação 4.4.1. 4.4.1. Limpeza de área: intervenção de áreas em processo de regeneração Se a conversão/compensação ocorrer devido a uma exigência legal (em nível nacional ou local) ou emergência verificável (como firewalls), este indicador não se aplica. As obrigações legais podem incluir - mas não se limitar a - a necessidade de estradas, linhas de transmissão, etc. Sob certas circunstâncias, um nível mínimo de conversão pode ocorrer se houver um plano de restauração em vigor. Consulte o Anexo 8 e a definição de “nível mínimo de conversão” no glossário, de acordo com a Accountability Framework Initiative.', '4.4 A expansão do cultivo de soja é responsável. As definições da Accountability Framework são reconhecidas pela aplicabilidade desses critérios.', TRUE, 66),
('Princípio 4: Responsabilidade Ambiental', '4.4.1.a', 'Quando houver mapas RTRS disponíveis: todas as áreas incluídas na Categoria 1 dos mapas.', '', 'Orientação 4.4.1. 4.4.1. Limpeza de área: intervenção de áreas em processo de regeneração Se a conversão/compensação ocorrer devido a uma exigência legal (em nível nacional ou local) ou emergência verificável (como firewalls), este indicador não se aplica. As obrigações legais podem incluir - mas não se limitar a - a necessidade de estradas, linhas de transmissão, etc. Sob certas circunstâncias, um nível mínimo de conversão pode ocorrer se houver um plano de restauração em vigor. Consulte o Anexo 8 e a definição de “nível mínimo de conversão” no glossário, de acordo com a Accountability Framework Initiative.', '4.4 A expansão do cultivo de soja é responsável. As definições da Accountability Framework são reconhecidas pela aplicabilidade desses critérios.', TRUE, 67),
('Princípio 4: Responsabilidade Ambiental', '4.4.1.b', 'Quando não houver mapas RTRS disponíveis:
a) florestas nativas; b) matas ciliares; c) zonas úmidas naturais; d) encostas íngremes; e) zonas designadas por lei para servir o objetivo de conservação nativa e / ou proteção cultural e social.', '', 'Orientação 4.4.1. 4.4.1. Limpeza de área: intervenção de áreas em processo de regeneração Se a conversão/compensação ocorrer devido a uma exigência legal (em nível nacional ou local) ou emergência verificável (como firewalls), este indicador não se aplica. As obrigações legais podem incluir - mas não se limitar a - a necessidade de estradas, linhas de transmissão, etc. Sob certas circunstâncias, um nível mínimo de conversão pode ocorrer se houver um plano de restauração em vigor. Consulte o Anexo 8 e a definição de “nível mínimo de conversão” no glossário, de acordo com a Accountability Framework Initiative.', '4.4 A expansão do cultivo de soja é responsável. As definições da Accountability Framework são reconhecidas pela aplicabilidade desses critérios.', TRUE, 68),
('Princípio 4: Responsabilidade Ambiental', '4.4.1.c', 'Quando houver reivindicações nãoresolvidas sobre o uso da terra por parte dos usuários tradicionais da terra em litígio, sem acordo entre as partes.', '', 'Orientação 4.4.1. 4.4.1. Limpeza de área: intervenção de áreas em processo de regeneração Se a conversão/compensação ocorrer devido a uma exigência legal (em nível nacional ou local) ou emergência verificável (como firewalls), este indicador não se aplica. As obrigações legais podem incluir - mas não se limitar a - a necessidade de estradas, linhas de transmissão, etc. Sob certas circunstâncias, um nível mínimo de conversão pode ocorrer se houver um plano de restauração em vigor. Consulte o Anexo 8 e a definição de “nível mínimo de conversão” no glossário, de acordo com a Accountability Framework Initiative.

Orientação 4.4.1.c Os usuários tradicionais da terra apresentarão provas razoáveis de que vêm exercendo o uso ou o acesso à área da propriedade durante os 10 anos anteriores a maio de 2009.', '4.4 A expansão do cultivo de soja é responsável. As definições da Accountability Framework são reconhecidas pela aplicabilidade desses critérios.', TRUE, 69),
('Princípio 4: Responsabilidade Ambiental', '4.4.2', 'Depois de 3 de junho de 2016, não é permitida qualquer conversão de terras naturais (ver Glossário) ou encostas íngremes e em áreas designadas por lei para servir o objetivo de conservação nativa e / ou proteção cultural e social. (deve verificar se houve abertura entre 2009 a 2016, esta nao deve ter ocorrido nas areas de categoria 1)', 'Imediata', '', '4.4 A expansão do cultivo de soja é responsável. As definições da Accountability Framework são reconhecidas pela aplicabilidade desses critérios.', TRUE, 70),
('Princípio 4: Responsabilidade Ambiental', '4.5.1', 'Existe um mapa da fazenda indicando a vegetação nativa, as áreas de produção e os cursos d''água (ver 5.2.1).', 'Imediata', 'Orientação 4.5.1 Na certificação grupal, o gestor do grupo pode manter o mapa centralmente.', '4.5 A biodiversidade da fazenda é mantida e resguardada através da preservação da vegetação nativa.', TRUE, 71),
('Princípio 4: Responsabilidade Ambiental', '4.5.2', 'Existe um plano em implementação e monitoramento para garantir que a vegetação nativa e a vida silvestre sejam mantidas.(anexo 5 da interpretação nacional, ex mapeamento de plantas e animais presentes na reserva e assim desenvolve um plano de ação para preservação destas especies). ex: placas de proibição de caça.', 'Curto prazo', 'Orientação 4.5.2 O plano deve incluir, no mínimo, o seguinte: • Identificação da vegetação nativa e da vida silvestre existentes na fazenda. • Indicadores e linha de base do estado da vegetação nativa e da vida silvestre. • Medidas para preservar a vegetação nativa e a vida silvestre. • Monitoramento O Anexo 5 exemplifica a elaboração de um plano para esse indicador. O plano é realizado por uma pessoa adequadamente capacitada e experiente nesta tarefa (como 4.1.2). Como comprovação, essa pessoa apresentará comprovante de frequência em cursos e capacitação e a experiência descrita em seu currículo.', '4.5 A biodiversidade da fazenda é mantida e resguardada através da preservação da vegetação nativa.', TRUE, 72),
('Princípio 4: Responsabilidade Ambiental', '4.5.3', 'As espécies raras, ameaçadas ou em perigo presentes permanentemente ou temporariamente na propriedade estão protegidas. A caça ou coleta dessas espécies não é permitida.', 'Imediata', 'Orientação 4.5.3 A caça é proibida no Brasil. Referência: Lei 5197. Estas ações devem estar previstas no plano 4.5.2', '4.5 A biodiversidade da fazenda é mantida e resguardada através da preservação da vegetação nativa.', TRUE, 73),
('Princípio 4: Responsabilidade Ambiental', '4.5.4', 'Nas fazendas com menos de 10% de vegetação nativa (mas em conformidade com 4.4 e 5.2, bem como outros indicadores relacionados), os produtores devem de implementar e promover atividades de conservação dentro, fora ou ao redor da fazenda para incentivar a vida silvestre e a restauração da vegetação nativa', 'Curto prazo', 'Orientação 4.5.4 Algumas atividades que os produtores podem realizar para cumprir com este indicador são, mas não estão limitadas às seguintes: • deixar corredores ou restaurar fronteiras cercadas ou caminhos • restaurar áreas degradadas ou improdutivas, • apoiar atividades de conservação ou restauração fora dos limites da fazenda (porém relacionadas à fauna local e à vegetação nativa) – p. ex: criação de viveiros de mudas florestais para posterior doação a organizações que atuam no estabelecimento de espécies, colaboração com instituições voltadas para atividades de conservação. Este apoio pode ser oferecido através de financiamento ou do fornecimento de recursos, materiais, pessoal, etc. Os produtores podem criar grupos para cumprir esse indicador e organizar atividades para promover ações de conservação dentro, fora ou em torno da fazenda. As áreas compensadas ou desoneradas de Reserva Legal em outras localidades entram no cômputo dos 10% do indicador.', '4.5 A biodiversidade da fazenda é mantida e resguardada através da preservação da vegetação nativa.', TRUE, 74),
('Princípio 5: Boas Práticas Agrícolas', '5.1.1', 'Boas práticas agrícolas são implementadas para promover a recarga do aquífero e minimizar os impactos difusos e localizados de resíduos químicos, fertilizantes, erosão ou outras fontes sobre a qualidade das águas superficiais e subterrâneas. (investiga se na propiedade existe alguma fonte de agua contaminada, e as providencia tomada).', 'Curto prazo', '', '5.1 A qualidade e a oferta de águas superficiais e subterrâneas são mantidas ou melhoradas.', TRUE, 75),
('Princípio 5: Boas Práticas Agrícolas', '5.1.2', 'Existe um plano que inclui medidas de monitoramento e mitigação de acordo com os riscos identificados e o plano é aplicável à escala. (avaliação das ações tomadas)', 'Médio prazo', 'Orientação 5.1.2 O plano de monitoramento deve definir parâmetros - p.ex., pH, temperatura, oxigênio dissolvido, turbidez e condutividade elétrica, níveis de contaminação e frequência adequada de testagem. O monitoramento deve ser considerado em nível de bacia hidrográfica. Onde houver poços, eles devem ser utilizados para monitorar as águas subterrâneas. Para aguas superficiais deverão estar previstas as ações de mitigação. Para locais com o uso de águas subterrânea deverá ser realizada a análise laboratoriais. O laboratório de testes deve ser independente, mas não necessariamente certificado.', '5.1 A qualidade e a oferta de águas superficiais e subterrâneas são mantidas ou melhoradas.', TRUE, 76),
('Princípio 5: Boas Práticas Agrícolas', '5.1.3', 'Qualquer evidência direta de contaminação localizada de águas subterrâneas ou de superfície é relatada e monitorada em colaboração com as autoridades locais.', 'Imediata', '', '5.1 A qualidade e a oferta de águas superficiais e subterrâneas são mantidas ou melhoradas.', TRUE, 77),
('Princípio 5: Boas Práticas Agrícolas', '5.1.4', 'Onde houver irrigação, existe um procedimento documentado referente à aplicação das melhores práticas e cumprimento da legislação. (avaliar se a fazenda irriga com critério)', 'Curto prazo', 'Orientação 5.1.4 Quando houver irrigação, devem ser considerados outros usos potenciais - como o uso doméstico ou uso em outras culturas alimentares. Se faltar água, oconsumo humano terá prioridade.', '5.1 A qualidade e a oferta de águas superficiais e subterrâneas são mantidas ou melhoradas.', TRUE, 78),
('Princípio 5: Boas Práticas Agrícolas', '5.1.5', 'Os diferentes usos da água na propriedade devem ser identificados. Nas atividades que usam maiores volumes de água, o produtor deve encontrar uma forma de monitorá-la. Ações devem ser implementadas para reduzir o uso de água sempre que possível. (identificar de todos os pontos de capitação de agua, e momitorar o consumo respectivo). e identificar a atividade que utilizam essa agua)', 'Médio prazo', 'Orientação 5.1.5 As exigências legais e regulatórias são suficientes para o cumprimento deste indicador.', '5.1 A qualidade e a oferta de águas superficiais e subterrâneas são mantidas ou melhoradas.', TRUE, 79),
('Princípio 5: Boas Práticas Agrícolas', '5.2.1', 'As localizações de todos os cursos de água foram identificadas e mapeadas, inclusive a situação da vegetação ciliar.', 'Imediata', '', '5.2 As áreas de vegetação natural em volta de nascentes e ao longo cursos naturais de água são mantidas ou restabelecidas.', TRUE, 80),
('Princípio 5: Boas Práticas Agrícolas', '5.2.2', 'Nas áreas ciliares de onde a vegetação natural foi removida, existe um plano em vias de implementação com um cronograma de restauração.', 'Curto prazo', 'Orientação 5.2.2 Pelo menos 17% da vegetação ripária deve ser restaurada dentro de um prazo de 5 anos. Se a vegetação ripária (APPs) estiver degradada, o proprietário assinará um compromisso legal de restauração de vegetação ripária da autoridade competente (por exemplo, Licenciamento Ambiental TAC/PRAD) perante a agência estadual e esse compromisso legal será vistoriado anualmente. Caso o proprietário não tiver restaurado a vegetação, sua licença ambiental será retirada e, em conseqüência, ele/ela perderá a certificação. O produtor deve demonstrar 17% de restauração da vegetação ripária dentro do prazo de 5 anos até a restauração completa ou apresentar ou então, apresentar o compromisso legal de restaurar a vegetação ripária (por exemplo, PRAD). Para pequenos produtores / produtores familiares, 10% da vegetação ripária deverá ser restaurada dentro do prazo de 5 anos. A vegetação ripária é: Toda vegetação ao longo de cursos de água em seu nível mais alto, cuja largura mínima deverá ser: -30 m para cursos de água com menos de 10 m de largura; -50 m para cursos de água com 10 a 50m de largura; -100m para cursos de água com 50 a 200m de largura; -Cabeceiras, mesmo que intermitentes, com um rádio de largura de 50 m; -Em volta de lagos e lagoas naturais ou artificiais, 100 m de largura. Este indicador aplica os requisitos do critério 4.4.', '5.2 As áreas de vegetação natural em volta de nascentes e ao longo cursos naturais de água são mantidas ou restabelecidas.', TRUE, 81),
('Princípio 5: Boas Práticas Agrícolas', '5.2.3', 'As áreas úmidas naturais não são drenadas e a vegetação nativa é mantida. (não pode ter ponto de capitação em areas umidas naturais) não pode drenar area natural.', 'Imediata', 'Orientação 5.2.3 A data-limite para as zonas úmidas naturais é maio de 2009. Na certificação grupal de pequenos produtores, os gestores dos grupos podem manter os mapas centralmente e podem ser responsáveis por manter e desenvolver planos de restauração.', '5.2 As áreas de vegetação natural em volta de nascentes e ao longo cursos naturais de água são mantidas ou restabelecidas.', TRUE, 82),
('Princípio 5: Boas Práticas Agrícolas', '5.3.1', 'Já ocorre o monitoramento adequado da qualidade do solo, incluindo a coleta de amostras (matéria orgânica do solo) para avaliação da fertilidade.', 'Médio prazo', 'Orientação 5.3.1 Identificar indicadores adequados de monitoramento, que devem basear-se nas principais questões relativas ao tipo de produção e à região. Sejam quais forem os indicadores de monitoramento, eles devem ser simples e produzir informações confiáveis. Algumas sugestões incluem: Análise de matéria orgânica, total de nitrogênio (N) (o total de N pode ser estimado em 5% da matéria orgânica), fósforo (P), pH, condutividade eléctrica, medição de resíduos de superfície (qualidade e quantidade 30 dias antes da data média de semeio, com tolerância de +\- 10 dias).', '5.3 A qualidade do solo é mantida ou melhorada e a erosão é evitada através de boas práticas de manejo.', TRUE, 83),
('Princípio 5: Boas Práticas Agrícolas', '5.3.2', 'O conhecimento de técnicas para preservar a qualidade (física, química e biológica) do solo é demonstrado e essas técnicas estão implementadas. Pelo menos 20% devem ser plantio direto. Os produtores terão que justificar o motivo por que não puderam fazer o plantio direto. (entrevista com o agronomo e avaliação visual da propiedade)', 'Imediata', 'Orientação 5.3.2 As técnicas de manutenção da qualidade do solo podem incluir: • Agricultura de conservação. • Rotação de culturas. • Agricultura de precisão • Plantas fixadoras de nitrogênio • Adubos verdes • Fertilização equilibrada. As técnicas de controle da erosão do solo podem incluir: • Gestão das estradas dentro da fazenda. • Gestão das áreas inclinadas. • Manutenção da cobertura permanente do solo. • Plantio direto. • Semeadura em contorno', '5.3 A qualidade do solo é mantida ou melhorada e a erosão é evitada através de boas práticas de manejo.', TRUE, 84),
('Princípio 5: Boas Práticas Agrícolas', '5.3.3', 'O conhecimento das técnicas de controle da erosão do solo é demonstrado e essas técnicas são implementadas adequadamente.(entrevista e avaliação visual)', 'Imediata', 'Orientação 5.3.3. A RTRS reconhece que nem todos os produtores conseguirão transicionar todas as suas plantações para o plantio direto no curto prazo, então incentiva os produtores a planejarem a implementação progressiva do plantio direto ao longo do tempo. O plano de manejo do solo deve conter, no mínimo, as seguintes informações: • Amostragem do solo Plano de rotação de culturas, incluindo a rotação com gramíneas • Plano de cobertura de culturas • Tipo, qualidade e momento da fertilização, com esforços para manter os níveis atuais de fertilização ao mínimo. • Medidas para evitar a compactação do solo • Ferramentas para prevenir a erosão causada pelo vento e pela água. O plano terá duração mínima de uma rotação completa e será executado pelo Engenheiro Agrônomo responsável.', '5.3 A qualidade do solo é mantida ou melhorada e a erosão é evitada através de boas práticas de manejo.', TRUE, 85),
('Princípio 5: Boas Práticas Agrícolas', '5.3.4', 'Deverá ser elaborado um plano de rotação de culturas para evitar o plantio de soja imediatamente sobre soja e possibilitar um intervalo de tempo no campo em questão. Durante esse intervalo, deve ocorrer o cultivo de uma segunda cultura ou pastagem, ou, no mínimo, a terra deve ser deixada em pousio ou sob cobertura vegetal para regenerar. Este plano deve considerar a adaptação às condições climáticas e agroecológicas específicas da região. (apresentar um planejamento de safra, demonstrando em cada talhao) ex planilha de excel, word, e-mail.', 'Imediata', 'Orientação 5.3.4 A RTRS incentiva os produtores a realizarem a rotação de culturas. Se isso não for possível, os produtores deverão justificar sua decisão.', '5.3 A qualidade do solo é mantida ou melhorada e a erosão é evitada através de boas práticas de manejo.', TRUE, 86),
('Princípio 5: Boas Práticas Agrícolas', '5.4.1', 'Existe um plano de MIC documentado e implementado que aborda o uso da prevenção e outros controles biológicos, não químicos ou químicos seletos. (anexo 6 padrao rtrs)', 'Curto prazo', 'Orientação 5.4 Levar em conta a escala e o contexto, especialmente nas fazendas de pequeno porte - isto diz respeito tanto ao nível esperado de MIC quanto aos registros mantidos.', '5.4 Os impactos negativos de produtos fitossanitários sobre o meio ambiente e a saúde são reduzidos pela aplicação de técnicas sistemáticas e reconhecidas de Manejo Integrado de Culturas (MIC). Nota: Veja o Anexo 6 para mais informações sobre a MIC.', TRUE, 87),
('Princípio 5: Boas Práticas Agrícolas', '5.4.2', 'Existe um plano em vigor que contém metas de redução de produtos fitossanitários potencialmente prejudiciais ao longo do tempo. (pode ser incluido dentro do MIC)', 'Curto prazo', 'Orientação 5.4 Levar em conta a escala e o contexto, especialmente nas fazendas de pequeno porte - isto diz respeito tanto ao nível esperado de MIC quanto aos registros mantidos.

Orientação 5.4.2 Os parâmetros monitorados incluem o número de aplicações de produtos fitossanitários por safra, volume de produtos fitossanitários utilizados por hectare e classe toxicológica do produto. Para os fins deste Critério, os níveis de dano potencial de um produto fitossanitário podem ser determinados a partir de sua classificação pela OMS. Quando as metas não são atingidas, são apresentadas justificativas na forma de evidências documentais. Incentiva-se os produtores a considerarem o uso de produtos biológicos.', '5.4 Os impactos negativos de produtos fitossanitários sobre o meio ambiente e a saúde são reduzidos pela aplicação de técnicas sistemáticas e reconhecidas de Manejo Integrado de Culturas (MIC). Nota: Veja o Anexo 6 para mais informações sobre a MIC.', TRUE, 88),
('Princípio 5: Boas Práticas Agrícolas', '5.4.3', 'Devem ser utilizados apenas os produtos agroquímicos originais e genuínos que atendem aos requisitos locais de registo, para prevenir riscos para os agricultores, os consumidores e o meio-ambiente. (nota fiscal e receiturario agronomico)', 'Imediata', 'Orientação 5.4 Levar em conta a escala e o contexto, especialmente nas fazendas de pequeno porte - isto diz respeito tanto ao nível esperado de MIC quanto aos registros mantidos.

Orientação 5.4.3 Produtos registrados apenas para a cultura da soja e nas dosagens recomendadas. Verificar a existência do receituário agronômico.', '5.4 Os impactos negativos de produtos fitossanitários sobre o meio ambiente e a saúde são reduzidos pela aplicação de técnicas sistemáticas e reconhecidas de Manejo Integrado de Culturas (MIC). Nota: Veja o Anexo 6 para mais informações sobre a MIC.', TRUE, 89),
('Princípio 5: Boas Práticas Agrícolas', '5.4.4', 'O uso de produtos agroquímicos segue as exigências legais e recomendações profissionais (ou, se não houver recomendações profissionais disponíveis, as recomendações do fabricante) e inclui a rotatividade dos princípios ativos para evitar a criação de resistência. (nota fiscal e receiturario agronomico) da atual safra', 'Imediata', 'Orientação 5.4 Levar em conta a escala e o contexto, especialmente nas fazendas de pequeno porte - isto diz respeito tanto ao nível esperado de MIC quanto aos registros mantidos.

Orientação 5.4.4 As leis locais e nacionais devem ser levadas em consideração. Levar em consideração a escala e o contexto especialmente para pequenos produtores – isto envolve o nível do MIC esperado e os registros mantidos. Os produtores devem armazenar as fichas de segurança dos produtos nomesmo local onde os produtos são manuseados, de modo que estejam facilmente acessíveis quando necessário.', '5.4 Os impactos negativos de produtos fitossanitários sobre o meio ambiente e a saúde são reduzidos pela aplicação de técnicas sistemáticas e reconhecidas de Manejo Integrado de Culturas (MIC). Nota: Veja o Anexo 6 para mais informações sobre a MIC.', TRUE, 90),
('Princípio 5: Boas Práticas Agrícolas', '5.4.5', 'Há registros do monitoramento de pragas, doenças, ervas daninhas e predadores naturais (monitoramento, data, talhao, pagras encontradas)', 'Curto prazo', 'Orientação 5.4 Levar em conta a escala e o contexto, especialmente nas fazendas de pequeno porte - isto diz respeito tanto ao nível esperado de MIC quanto aos registros mantidos.', '5.4 Os impactos negativos de produtos fitossanitários sobre o meio ambiente e a saúde são reduzidos pela aplicação de técnicas sistemáticas e reconhecidas de Manejo Integrado de Culturas (MIC). Nota: Veja o Anexo 6 para mais informações sobre a MIC.', TRUE, 91),
('Princípio 5: Boas Práticas Agrícolas', '5.5.1', 'Existem registros do uso de agroquímicos, incluindo:', 'Imediata', 'Orientação 5.5.1 Os registros são mantidos durante, pelo menos, 5 anos. Isto não se aplica aos registros de anos anteriores à certificação. A escala e o contexto devem ser levados em conta, principalmente nas fazendas de pequeno porte. Certas exceções podem ser abertas (por exemplo, quanto à manutenção de faturas) para as pequenas fazendas de um grupo, desde que o grupo disponha de um mecanismo para garantir o cumprimento do Critério. Mais informações exigidas: a) Fornecer detalhes do nome de marca e do ingrediente ativo do produto. b) Fazer coincidir o volume comprado, o volume aplicado e a dose recomendada na área de soja semeada. c) Os documentos de compra (notas fiscais/faturas) são apresentados.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 92),
('Princípio 5: Boas Práticas Agrícolas', '5.5.1.a', 'os produtos comprados e aplicados, as', 'Imediata', 'Orientação 5.5.1 Os registros são mantidos durante, pelo menos, 5 anos. Isto não se aplica aos registros de anos anteriores à certificação. A escala e o contexto devem ser levados em conta, principalmente nas fazendas de pequeno porte. Certas exceções podem ser abertas (por exemplo, quanto à manutenção de faturas) para as pequenas fazendas de um grupo, desde que o grupo disponha de um mecanismo para garantir o cumprimento do Critério. Mais informações exigidas: a) Fornecer detalhes do nome de marca e do ingrediente ativo do produto. b) Fazer coincidir o volume comprado, o volume aplicado e a dose recomendada na área de soja semeada. c) Os documentos de compra (notas fiscais/faturas) são apresentados.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 93),
('Princípio 5: Boas Práticas Agrícolas', '5.5.1.b', 'a identificação da área onde a aplicação foi', 'Imediata', 'Orientação 5.5.1 Os registros são mantidos durante, pelo menos, 5 anos. Isto não se aplica aos registros de anos anteriores à certificação. A escala e o contexto devem ser levados em conta, principalmente nas fazendas de pequeno porte. Certas exceções podem ser abertas (por exemplo, quanto à manutenção de faturas) para as pequenas fazendas de um grupo, desde que o grupo disponha de um mecanismo para garantir o cumprimento do Critério. Mais informações exigidas: a) Fornecer detalhes do nome de marca e do ingrediente ativo do produto. b) Fazer coincidir o volume comprado, o volume aplicado e a dose recomendada na área de soja semeada. c) Os documentos de compra (notas fiscais/faturas) são apresentados.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 94),
('Princípio 5: Boas Práticas Agrícolas', '5.5.1.c', 'os nomes das pessoas que fizeram a', 'Curto prazo', 'Orientação 5.5.1 Os registros são mantidos durante, pelo menos, 5 anos. Isto não se aplica aos registros de anos anteriores à certificação. A escala e o contexto devem ser levados em conta, principalmente nas fazendas de pequeno porte. Certas exceções podem ser abertas (por exemplo, quanto à manutenção de faturas) para as pequenas fazendas de um grupo, desde que o grupo disponha de um mecanismo para garantir o cumprimento do Critério. Mais informações exigidas: a) Fornecer detalhes do nome de marca e do ingrediente ativo do produto. b) Fazer coincidir o volume comprado, o volume aplicado e a dose recomendada na área de soja semeada. c) Os documentos de compra (notas fiscais/faturas) são apresentados.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 95),
('Princípio 5: Boas Práticas Agrícolas', '5.5.1.d', 'a identificação do equipamento de', 'Curto prazo', 'Orientação 5.5.1 Os registros são mantidos durante, pelo menos, 5 anos. Isto não se aplica aos registros de anos anteriores à certificação. A escala e o contexto devem ser levados em conta, principalmente nas fazendas de pequeno porte. Certas exceções podem ser abertas (por exemplo, quanto à manutenção de faturas) para as pequenas fazendas de um grupo, desde que o grupo disponha de um mecanismo para garantir o cumprimento do Critério. Mais informações exigidas: a) Fornecer detalhes do nome de marca e do ingrediente ativo do produto. b) Fazer coincidir o volume comprado, o volume aplicado e a dose recomendada na área de soja semeada. c) Os documentos de compra (notas fiscais/faturas) são apresentados.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 96),
('Princípio 5: Boas Práticas Agrícolas', '5.5.1.e', 'as condições meteorológicas durante a', 'Médio prazo', 'Orientação 5.5.1 Os registros são mantidos durante, pelo menos, 5 anos. Isto não se aplica aos registros de anos anteriores à certificação. A escala e o contexto devem ser levados em conta, principalmente nas fazendas de pequeno porte. Certas exceções podem ser abertas (por exemplo, quanto à manutenção de faturas) para as pequenas fazendas de um grupo, desde que o grupo disponha de um mecanismo para garantir o cumprimento do Critério. Mais informações exigidas: a) Fornecer detalhes do nome de marca e do ingrediente ativo do produto. b) Fazer coincidir o volume comprado, o volume aplicado e a dose recomendada na área de soja semeada. c) Os documentos de compra (notas fiscais/faturas) são apresentados.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 97),
('Princípio 5: Boas Práticas Agrícolas', '5.5.2', 'Os recipientes são devidamente armazenados, lavados e descartados; dejetos e resíduos de agroquímicos são descartados de modo ambientalmente adequado.(avaliação a campo e documental)', 'Imediata', 'Orientação 5.5.2 A lavagem dos recipientes deve ser realizada de acordo com os princípios da tripla lavagem (incluindo a reutilização da água de lavagem no tanque de mistura) ou através de técnicas de alta pressão associadas à aplicação mecânica. Em conformidade com a Lei 9974/2000, caso não haja instalações de recepção, os revendedores serão responsáveis pela recepção de embalagens vazias (os padrões regulamentares correspondentes podem ser consultados no Ministério do Trabalho). As embalagens são guardadas conforme as regulamentações NR31 e NR9843 e à orientação para fabricantes. As embalagens são lavadas usando-se os princípios da tríplice lavagem. Deve adicionar-se água à calda de pulverização e as embalagens são enviadas às instalações de recepção pertencentes ao INPEV (Instituto Nacional de Processamento de Embalagens). A calda de pulverização residual deve ser diluída com um traço 1:10 e aplicada em áreas de pousio, trilhas e de mata ciliar distantes dos cursos de água e em áreas com alto tráfego humano.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 98),
('Princípio 5: Boas Práticas Agrícolas', '5.5.3', 'O transporte e o armazenamento de agroquímicos são realizados de forma segura e são tomadas todas as devidas precauções relativas à saúde, meio ambiente e segurança. (avaliação visual)', 'Imediata', 'Orientação 5.5.3 As áreas utilizadas no armazenamento e distribuição de agroquímicos e substâncias inflamáveis e tóxicas são projetadas, construídas e equipadas para reduzir os riscos de acidentes e os impactos negativos sobre a saúde humana e o meio ambiente. Algumas sugestões para reduzir o risco de acidentes e impactos negativos são: acesso restrito, piso impermeável, área de armazenamento, barreira de contenção, fichas de segurança, instruções em caso de acidentes, equipamentos de proteção, extintores de incêndio, primeiros socorros, elementos de derramamento, ventilação mínima e / ou forçada, limpeza, separação de sementes, fertilizantes e produtos. Os requisitos legais devem ser seguidos nas fazendas de todos os portes. O transporte e armazenamento de agroquímicos conforme a regulamentação NR31 e a todos os procedimentos de precaução aplicáveis para a saúde, a segurança e o ambiente são implementados de acordo ao rótulo do produto e do fabricante (Folha Informativa de Produtos Químicos – FISPQ - e à folha informativa do produto para casos de emergência).', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 99),
('Princípio 5: Boas Práticas Agrícolas', '5.5.4', 'São tomadas as precauções necessárias para evitar a entrada de pessoas em áreas recentemente pulverizadas. (identificação da área e aviso a todos os funcionários) ex em refeitorios, local do relógio ponto e na área tratada', 'Imediata', 'Orientação 5.5.4 Seguir as instruções do rótulo sobre reentrada (Instrução da ANVISA - Agência Nacional de Vigilância Sanitária). As precauções podem incluir, por exemplo, capacitação sobre o assunto, sinalização das áreas pulverizadas ou um mecanismo que informe os colaboradores e atores externos sobre as áreas que foram pulverizadas.', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 100),
('Princípio 5: Boas Práticas Agrícolas', '5.5.5', 'Os fertilizantes são usados de acordo com as recomendações profissionais (fornecidas pelos fabricantes sempre que não houver outras recomendações profissionais disponíveis). (entrevista com agronomo da fazenda)', 'Curto prazo', '', '5.5 Toda aplicação de agroquímicos é documentada e há monitoramento de todo o armazenamento, manuseio, coleta e descarte de resíduos químicos e embalagens vazias para garantir a conformidade com as boas práticas.', TRUE, 101),
('Princípio 5: Boas Práticas Agrícolas', '5.6.1', 'Os agroquímicos listados nas Convenções de Estocolmo e Roterdã não são utilizados. (importante que os gestores saibam os produtos proibidos e ter conhecimento das convenções)', 'Imediata', 'Orientação 5.6.1 Convenção de Roterdã: http://www.pic.int/home.php?type=t&id=29&sid=30 Convenção de Estocolmo sobre Poluentes Orgânicos Persistentes (POP) http://chm.pops.int/Convention/ThePOPs/tabid/673/language/en-US/Default.aspx Além disso, para a Interpretação Nacional do Brasil, foi decidido que o Endosulfan não deve ser utilizado desde junho de 2013. O Paraquat e Carbofuran estão proibidos de acordo com as Convenções de Estocolmo e Roterdã.', '5.6 Uso Responsável de Agroquímicos.', TRUE, 102),
('Princípio 5: Boas Práticas Agrícolas', '5.6.2', 'Os agroquímicos devem ser aplicados usando métodos que minimizem os danos à saúde humana, vida selvagem, biodiversidade vegetal e qualidade da água e do ar. (este indicador pode ser eliminado pelo MIC)', 'Imediata', '', '5.6 Uso Responsável de Agroquímicos.', TRUE, 103),
('Princípio 5: Boas Práticas Agrícolas', '5.7.1', 'Existem informações sobre os requisitos de uso de agentes de controle biológico.', 'Curto prazo', 'Orientação 5.7 Os registros de uso de agentes de controle biológico devem ser usados como prova de conformidade com este critério.

Orientação 5.7.1 O controle biológico é utilizado tanto para a produção orgânica quanto para a convencional. A lei que regulamenta o uso do controle biológico na produção orgânica é a “Instrução Normativa 64 de 18.12.2008 para substâncias e práticas permitidas para manejo e controle de pragas e doenças nos vegetais em sistemas orgânicos de produção” e o Decreto N° 6.913, de 23 de julho de 2009, que cria um novo grupo de produtos fitossanitários para a produção orgânica. As Leis que regulamentam o uso do controle biológico na produção convencional são a Lei Nacional 7802/89 (Lei de Agrotóxicos), que inclui o controle biológico. Para ambos os tipos de produção, deve ser solicitada uma autorização ao OAC ou OCS, OAC: Organismo de Avaliação da Conformidade. OCS: Organização de Controle Social.', '5.7 O uso de agentes de controle biológico é documentado, monitorado e controlado de acordo com as leis nacionais e protocolos científicos aceitos internacionalmente.', TRUE, 104),
('Princípio 5: Boas Práticas Agrícolas', '5.7.2', 'São mantidos registros de todo o uso de agentes de controle biológico, demonstrando conformidade com as leis nacionais. (Avaliação na fazenda se existe o uso de produtos biológicos)', 'Médio prazo', 'Orientação 5.7 Os registros de uso de agentes de controle biológico devem ser usados como prova de conformidade com este critério.

Orientação 5.7.2 A escala e o contexto devem ser levados em conta, principalmente nas pequenas fazendas.', '5.7 O uso de agentes de controle biológico é documentado, monitorado e controlado de acordo com as leis nacionais e protocolos científicos aceitos internacionalmente.', TRUE, 105),
('Princípio 5: Boas Práticas Agrícolas', '5.8.1', 'Em casos onde há sistemas institucionais destinados a identificar e monitorar novas pragas e espécies invasoras introduzidas, ou grandes surtos de pragas existentes, os produtores seguem as exigências desses sistemas para minimizar sua proliferação.', 'Curto prazo', '', '5.8 Os produtores não podem introduzir ou usar espécies invasoras na unidade de manejo. Medidas sistemáticas são planejadas e implementadas para monitorar, controlar e minimizar a sua proliferação e o desenvolvimento de novas pragas', TRUE, 106),
('Princípio 5: Boas Práticas Agrícolas', '5.8.2', 'Nos casos em que não há tais sistemas, as incidências de novas pragas ou espécies invasoras e grandes surtos de pragas existentes são comunicados às autoridades competentes e às organizações de produtores ou órgãos de pesquisa relevantes.', 'Curto prazo', 'Orientação 5.8.2 O Produtor deveria comunicar aos Departamentos de Agricultura dos municípios e à EMBRAPA acerca de quaisquer praga nova ou espécies invasoras e de surtos importantes de pragas existentes. Os produtores têm um procedimento que examina as tarefas de monitoramento e as comunicações às autoridades correspondentes.', '5.8 Os produtores não podem introduzir ou usar espécies invasoras na unidade de manejo. Medidas sistemáticas são planejadas e implementadas para monitorar, controlar e minimizar a sua proliferação e o desenvolvimento de novas pragas', TRUE, 107),
('Princípio 5: Boas Práticas Agrícolas', '5.9.1', 'Existem procedimentos documentados que especificam as boas práticas agrícolas relativas à aplicação de agroquímicos - incluindo a minimização da deriva - e estes procedimentos são implementados. (incluido dentro do MIC)', 'Curto prazo', 'Orientação 5.9.1 Os fatores que influenciam a deriva incluem, entre outros, a velocidade e a direção do vento, a temperatura, os equipamentos utilizados e a topografia.

Orientação 5.9.1- 5.9.2 Os requisitos referentes às pequenas fazendas devem ser adequados à escala e ao contexto. Na certificação grupal de pequenas fazendas - os gestores do grupo podem fornecer procedimentos documentados e manter registros das condições climáticas. No Plano de Manejo do Ministério da Indústria e do Comércio deve haver uma descrição dos procedimentos para a fumigação aérea conforme a IN- 02 (3 de janeiro de 2008). -A fumigação aérea de agrotóxicos deverá ser feita em áreas localizadas a uma distância mínima de: -500 m de vilarejos, cidades, povoados, bairros, fontes de água para o fornecimento de populações e -250 m de fontes de água, residências isoladas e rebanhos de animais. Referência: Site SISLEGIS, Regulamentação N° 2, 3 de janeiro de 2008 http://extranet.agricultura.gov.br/sislegisconsulta/consultarLegislacao.do?operacao=visualizar&id=18434', '5.9 Medidas adequadas são implantadas para evitar a deriva de agroquímicos para áreas vizinhas.', TRUE, 108),
('Princípio 5: Boas Práticas Agrícolas', '5.9.2', 'São mantidos registros das condições climáticas (velocidade e direção do vento, temperatura e umidade relativa) durante as operações de pulverização.', 'Médio prazo', 'Orientação 5.9.1- 5.9.2 Os requisitos referentes às pequenas fazendas devem ser adequados à escala e ao contexto. Na certificação grupal de pequenas fazendas - os gestores do grupo podem fornecer procedimentos documentados e manter registros das condições climáticas. No Plano de Manejo do Ministério da Indústria e do Comércio deve haver uma descrição dos procedimentos para a fumigação aérea conforme a IN- 02 (3 de janeiro de 2008). -A fumigação aérea de agrotóxicos deverá ser feita em áreas localizadas a uma distância mínima de: -500 m de vilarejos, cidades, povoados, bairros, fontes de água para o fornecimento de populações e -250 m de fontes de água, residências isoladas e rebanhos de animais. Referência: Site SISLEGIS, Regulamentação N° 2, 3 de janeiro de 2008 http://extranet.agricultura.gov.br/sislegisconsulta/consultarLegislacao.do?operacao=visualizar&id=18434', '5.9 Medidas adequadas são implantadas para evitar a deriva de agroquímicos para áreas vizinhas.', TRUE, 109),
('Princípio 5: Boas Práticas Agrícolas', '5.9.3', 'A aplicação aérea de pesticidas é realizada de tal maneira que não tenha impacto sobre áreas povoadas. Todas as aplicações aéreas são precedidas de notificações aos residentes dentro de um raio de 500m da aplicação planejada.', 'Imediata', 'Observação: ‘Áreas povoadas’ abrangem qualquer escritório, casa ou edificação ocupada', '5.9 Medidas adequadas são implantadas para evitar a deriva de agroquímicos para áreas vizinhas.', TRUE, 110),
('Princípio 5: Boas Práticas Agrícolas', '5.9.4', 'Não ocorre aplicação aérea de agroquímicos nas Classes Ia, Ib e II da OMS dentro de um raio de 500m de áreas povoadas ou corpos d''água.', 'Imediata', 'Orientação 5.9.4 No Brasil, as classes Ia, Ib e 2 da OMS correspondem à classificação toxicológica I & II. (Ver Anexo 8: Classe IA, IB e II da OMS) Os fatores que influenciam a deriva incluem, entre outros, a velocidade e direção do vento, a temperatura no momento da aplicação, os equipamentos utilizados e a topografia.', '5.9 Medidas adequadas são implantadas para evitar a deriva de agroquímicos para áreas vizinhas.', TRUE, 111),
('Princípio 5: Boas Práticas Agrícolas', '5.9.5', 'Não ocorre aplicação de pesticidas dentro de um raio de 30m de áreas povoadas ou corpos d''água.', 'Imediata', 'Orientação 5.9.5 Não se aplica para a aplicação manual de químicos não classificados como Ia, Ib ou II da OMS, se medidas adequadas forem tomadas para evitar a deriva (por exemplo, o uso de pulverizador costal manual com acessórios de proteção) e se for permitido pela lei e recomendações do fabricante). As comunicações podem ser feitas de acordo às possibilidades locais (rádio, SMS, rojão de aviso).', '5.9 Medidas adequadas são implantadas para evitar a deriva de agroquímicos para áreas vizinhas.', TRUE, 112),
('Princípio 5: Boas Práticas Agrícolas', '5.10.1', 'São tomadas medidas para evitar a interferência nos sistemas de produção das áreas vizinhas.', 'Curto prazo', 'Orientação 5.10.1 Sempre que é introduzida uma mudança nas práticas de produção de soja que possa impactar os sistemas vizinhos de produção, o produtor responsável pela mudança deve implementar uma faixa de amortecimento (buffer) de 30 m (por exemplo, em áreas onde a produção costuma ser GM, cabe ao agricultor orgânico ou não-GM manter a zona de amortecimento em torno de sua produção. Nas áreas com produção principalmente não-GM ou orgânica, os agricultores que plantam culturas GM ou usam produtos químicos devem manter uma faixa de amortecimento). Em países ou regiões onde já está aprovado que uma faixa de amortecimento menor que 30 metros é suficiente para prevenir a contaminação e preservar a pureza dos sistemas vizinhos, a faixa de amortecimento poderá ser menor e definida de acordo com as práticas nacionais. Em situações onde houver interferência nos sistemas de produção das áreas vizinhas e onde não foi alcançado o consenso entre as partes, os demandantes podem: a. Recorrer a procedimentos oficiais (ou procedimentos de classe, por exemplo, sindicais) para a resolução de disputas, b. enviar uma reclamação formal ao organismo de certificação. Referência para plantio de Soja-GM: Decreto 5591, 22 de novembro de 2005, que regulamenta as disposições da Lei 11105, 24 de março de 2005.', '5.10 São implementadas as medidas apropriadas para possibilitar a coexistência de sistemas de produção distintos.', TRUE, 113),
('Princípio 5: Boas Práticas Agrícolas', '5.11.1', 'Todas as sementes compradas devem vir de fontes de qualidade legalmente provada.', 'Imediata', 'Orientação 5.11.1 Referência: Lei 10711 (5 de agosto de 2003) Definição de “fontes de qualidade legalmente conhecidas”. São exigidas faturas/recibos Os produtores podem utilizar suas próprias sementes, respeitando as normas legais.', '5.11 A origem das sementes é controlada para melhorar a produção e prevenir a introdução de novas doenças.', TRUE, 114),
('Princípio 5: Boas Práticas Agrícolas', '5.11.2', 'Podem ser usadas sementes auto propagadas, desde que as normas adequadas de produção das sementes sejam seguidas e os requisitos legais referentes aos direitos de propriedade intelectual sejam cumpridos.', 'Imediata', 'Orientação 5.11.2 Referência: Lei 9456 (25 de abril de 1997) Exceção para pequenos produtores, conforme definido no artigo 10 da Lei 9456, que cumprem simultaneamente com os requisitos seguintes: I- explorar parcela de terra como proprietário, arrendatário, inquilino ou parceiro; II – manter até dois funcionários permanentes, sendo admitida a ajuda eventual de outros, quando a natureza sazonal das atividades o requererem; III – não ter, sob nenhum aspecto, uma área de mais de quatro módulos determinados de acordo à lei; IV – ter pelo menos oitenta por cento de renda bruta anual derivada da exploração agrícola ou extrativa; e V – residir na propriedade ou perto de área urbana ou rural,', '5.11 A origem das sementes é controlada para melhorar a produção e prevenir a introdução de novas doenças.', TRUE, 115);
